const PLANT_STATES=new Set(["Tamil Nadu","Madhya Pradesh","Uttarakhand"]);
const MAP_W=480,MAP_H=560;

/* ═══ LANDING PAGE ═══ */
function LandingPage({onEnter}){
  const [hov,setHov]=useState(null);
  const [sel,setSel]=useState(null);
  const hovP=hov?PLANTS.find(p=>p.id===hov):null;
  const selP=sel?PLANTS.find(p=>p.id===sel):null;
  return(<div style={{minHeight:"100vh",background:C.bg,fontFamily:"'IBM Plex Sans',system-ui,sans-serif",color:C.tx,display:"flex",flexDirection:"column",position:"relative",overflow:"hidden"}}>

    {/* Header */}
    <div style={{background:C.cd,borderBottom:"1px solid "+C.bd,padding:"0 24px",height:84,display:"flex",alignItems:"center",justifyContent:"space-between",position:"relative",zIndex:10,boxShadow:"0 1px 4px rgba(0,0,0,.05)"}}>
      <div style={{display:"flex",alignItems:"center",gap:12}}>
        <img src={LOGO} alt="JK Tyre" style={{height:70,objectFit:"contain"}}/>
        <div style={{width:1,height:24,background:C.bd}}/>
        <div><div style={{fontSize:18,fontWeight:700,letterSpacing:".3px"}}>One Factory</div><div style={{fontSize:12,color:C.mu,textTransform:"uppercase",letterSpacing:".8px",fontWeight:600,marginTop:1}}>One Dashboard</div></div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        <span style={{fontSize:13,color:C.mu,padding:"4px 10px",border:"1px solid "+C.bd,borderRadius:6,background:C.c2}}>FY 2025-26</span>
        <UserMenu plant={null} role="PH"/>
      </div>
    </div>

    {/* Main — Cards Left, Map Right */}
    <div style={{flex:1,display:"flex",alignItems:"stretch",padding:"20px 28px",gap:20,position:"relative",zIndex:1,overflow:"hidden"}}>

      {/* Left — Plant KPI Cards */}
      <div style={{width:280,minWidth:280,display:"flex",flexDirection:"column",gap:10,justifyContent:"center"}}>
        <div style={{fontSize:12,fontWeight:700,color:C.mu,textTransform:"uppercase",letterSpacing:"1.5px",marginBottom:2,paddingLeft:4}}>Plant Performance</div>
        {PLANTS.map((p,idx)=>{const active=sel===p.id;const isH=hov===p.id;return(<div key={p.id} onClick={()=>setSel(p.id)} onMouseEnter={()=>setHov(p.id)} onMouseLeave={()=>setHov(null)} style={{background:C.cd,borderRadius:12,border:"1px solid "+(active?C.aB:isH?C.ac+"44":C.bd),padding:"16px 18px",cursor:"pointer",transition:"all .2s",boxShadow:active?"0 4px 16px rgba(232,101,26,.1)":isH?"0 2px 8px rgba(0,0,0,.06)":"0 1px 3px rgba(0,0,0,.03)",transform:isH&&!active?"translateX(4px)":"none"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
            <div style={{width:36,height:36,borderRadius:10,background:active?C.aL:C.c2,display:"flex",alignItems:"center",justifyContent:"center",fontSize:17,color:active?C.ac:C.mu,fontWeight:700,border:"1px solid "+(active?C.aB:C.bd),transition:"all .2s"}}>{idx+1}</div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:16,fontWeight:700,color:active?C.ac:C.tx}}>{p.name}</div>
              <div style={{fontSize:12,color:C.mu,marginTop:1}}>{p.sub}</div>
            </div>
            <div style={{fontSize:14,color:C.ac,fontWeight:600,opacity:active||isH?1:0,transition:"opacity .2s"}}>{"\u2192"}</div>
          </div>
          <div style={{display:"flex",gap:6}}>
            {[{l:"OE",v:p.oe},{l:"OTIF",v:p.otif},{l:"Yield",v:p.yield}].map(k=>(<div key={k.l} style={{flex:1,background:C.c2,borderRadius:8,padding:"10px 8px",textAlign:"center",border:"1px solid "+C.bd}}>
              <div style={{fontSize:11,color:C.mu,textTransform:"uppercase",letterSpacing:".5px",fontWeight:600,marginBottom:4}}>{k.l}</div>
              <div style={{fontSize:23,fontWeight:700,color:rc(k.v),lineHeight:1}}>{k.v}<span style={{fontSize:12,fontWeight:400,color:C.mu}}>%</span></div>
              <div style={{marginTop:6,height:3,background:C.bd,borderRadius:2,overflow:"hidden"}}><div style={{width:k.v+"%",height:"100%",background:rc(k.v),borderRadius:2,transition:"width .3s"}}/></div>
            </div>))}
          </div>
        </div>);})}
      </div>

      {/* Right — India Map */}
      <div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",minWidth:0}}>
        <div style={{position:"relative",width:"100%",maxWidth:MAP_W+32,background:C.cd,borderRadius:14,border:"1px solid "+C.bd,boxShadow:"0 4px 24px rgba(0,0,0,.06)",padding:16}}>
          <svg viewBox={`0 0 ${MAP_W} ${MAP_H}`} style={{width:"100%",height:"auto",display:"block"}}>
            <defs>
              <filter id="mg"><feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
              {/* Outline filter: creates a thin border around the merged silhouette of all states */}
              <filter id="outline" x="-5%" y="-5%" width="110%" height="110%">
                <feMorphology in="SourceAlpha" operator="dilate" radius="0.8" result="expanded"/>
                <feComposite in="expanded" in2="SourceAlpha" operator="out" result="ring"/>
                <feFlood floodColor="#6b7280" floodOpacity="1" result="color"/>
                <feComposite in="color" in2="ring" operator="in"/>
              </filter>
            </defs>
            {/* Fill layer: all states same color, no strokes — appears as unified shape */}
            <g>
              {SP.map((s,i)=>(<path key={i} d={s.d} fill="#eef1f6" stroke="none"/>))}
            </g>
            {/* Outline layer: same paths but run through outline filter to draw only outer border */}
            <g filter="url(#outline)">
              {SP.map((s,i)=>(<path key={"ol"+i} d={s.d} fill="#000" stroke="none"/>))}
            </g>

            {PLANTS.map(p=>{const isH=hov===p.id;const isS=sel===p.id;return(<g key={p.id} style={{cursor:"pointer"}} onMouseEnter={()=>setHov(p.id)} onMouseLeave={()=>setHov(null)} onClick={e=>{e.stopPropagation();setSel(p.id);}}>
              <circle cx={p.sx} cy={p.sy} r="14" fill="none" stroke={C.ac} strokeWidth="1.2" opacity="0.35"><animate attributeName="r" values="8;18;8" dur="2.5s" repeatCount="indefinite"/><animate attributeName="opacity" values="0.5;0;0.5" dur="2.5s" repeatCount="indefinite"/></circle>
              <circle cx={p.sx} cy={p.sy} r="10" fill="none" stroke={C.ac} strokeWidth="0.8" opacity="0.25"><animate attributeName="r" values="6;14;6" dur="2.5s" repeatCount="indefinite" begin="0.4s"/><animate attributeName="opacity" values="0.35;0;0.35" dur="2.5s" repeatCount="indefinite" begin="0.4s"/></circle>
              <circle cx={p.sx} cy={p.sy} r={isH||isS?"7":"5.5"} fill={C.ac} stroke="#fff" strokeWidth="2.5" filter="url(#mg)" style={{transition:"all .2s"}}/>
              <text x={p.sx} y={p.sy-14} fill={isH?"#1A1D26":"#4A5168"} fontSize={isH?"9":"8"} fontWeight="700" textAnchor="middle" fontFamily="'IBM Plex Sans',system-ui" style={{transition:"all .2s"}}>{p.name}</text>
            </g>);})}
          </svg>

          {hovP&&!sel&&(<div style={{position:"absolute",left:`${(hovP.sx/(MAP_W))*100}%`,top:`${((hovP.sy/(MAP_H))*100)-2}%`,transform:"translate(-50%,-100%)",background:"rgba(255,255,255,0.97)",backdropFilter:"blur(12px)",border:"1px solid "+C.bd,borderRadius:10,padding:"12px 16px",minWidth:180,boxShadow:"0 8px 30px rgba(0,0,0,.12)",pointerEvents:"none",zIndex:20}}>
            <div style={{fontSize:14,fontWeight:700,color:C.ac,marginBottom:2}}>{hovP.name}</div>
            <div style={{fontSize:11,color:C.mu,marginBottom:8}}>{hovP.sub}</div>
            <div style={{display:"flex",gap:12}}>
              {[{l:"OE",v:hovP.oe,c:rc(hovP.oe)},{l:"OTIF",v:hovP.otif,c:rc(hovP.otif)},{l:"Yield",v:hovP.yield,c:rc(hovP.yield)}].map(k=>(<div key={k.l} style={{textAlign:"center"}}>
                <div style={{fontSize:11,color:C.mu,textTransform:"uppercase",letterSpacing:".5px",marginBottom:2}}>{k.l}</div>
                <div style={{fontSize:18,fontWeight:700,color:k.c}}>{k.v}%</div>
              </div>))}
            </div>
            <div style={{position:"absolute",bottom:-6,left:"50%",width:12,height:12,background:"rgba(255,255,255,0.97)",border:"1px solid "+C.bd,borderTop:"none",borderLeft:"none",transform:"translateX(-50%) rotate(45deg)"}}/>
          </div>)}
        </div>
      </div>

    </div>

    {/* Function Modal */}
    {selP&&(<div style={{position:"fixed",inset:0,zIndex:100,display:"flex",alignItems:"center",justifyContent:"center"}} onClick={()=>setSel(null)}>
      <div style={{position:"absolute",inset:0,background:"rgba(0,0,0,.25)",backdropFilter:"blur(4px)"}}/>
      <div onClick={e=>e.stopPropagation()} style={{position:"relative",background:C.cd,borderRadius:16,border:"1px solid "+C.bd,padding:"28px 32px",width:420,maxWidth:"90vw",boxShadow:"0 24px 60px rgba(0,0,0,.12)",animation:"modalIn .25s ease"}}>
        <button onClick={()=>setSel(null)} style={{position:"absolute",top:14,right:14,width:28,height:28,borderRadius:"50%",border:"1px solid "+C.bd,background:C.c2,color:C.mu,fontSize:17,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>{"\u2715"}</button>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:6}}>
          <div style={{width:10,height:10,borderRadius:"50%",background:C.ac}}/>
          <div style={{fontSize:19,fontWeight:700}}>{selP.name}</div>
        </div>
        <div style={{fontSize:13,color:C.mu,marginBottom:16}}>{selP.sub}</div>
        <div style={{display:"flex",gap:12,padding:"10px 14px",background:C.c2,borderRadius:8,marginBottom:20,border:"1px solid "+C.bd}}>
          {[{l:"OE",v:selP.oe},{l:"OTIF",v:selP.otif},{l:"Yield",v:selP.yield}].map(k=>(<div key={k.l} style={{flex:1,textAlign:"center"}}>
            <div style={{fontSize:11,color:C.mu,textTransform:"uppercase",letterSpacing:".4px",marginBottom:2}}>{k.l}</div>
            <div style={{fontSize:19,fontWeight:700,color:rc(k.v)}}>{k.v}<span style={{fontSize:12,fontWeight:400}}>%</span></div>
          </div>))}
        </div>
        <div style={{fontSize:12,color:C.mu,textTransform:"uppercase",letterSpacing:"1px",fontWeight:700,marginBottom:10}}>Select Function</div>
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {FUNCTIONS.map(f=>(<div key={f.id} onClick={f.active?()=>onEnter(selP,f.id):undefined} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",borderRadius:10,border:"1px solid "+(f.active?C.aB:C.bd),background:f.active?C.aL:C.c2,cursor:f.active?"pointer":"default",opacity:f.active?1:0.5,transition:"all .15s"}} onMouseEnter={e=>{if(f.active)e.currentTarget.style.borderColor=C.ac;}} onMouseLeave={e=>{if(f.active)e.currentTarget.style.borderColor="rgba(232,101,26,.28)";}}>
            <div style={{width:34,height:34,borderRadius:8,background:f.active?"rgba(232,101,26,.12)":"rgba(139,145,165,.08)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:19,color:f.active?C.ac:C.mu}}>{f.icon}</div>
            <div style={{flex:1}}>
              <div style={{fontSize:15,fontWeight:600,color:f.active?C.tx:C.mu}}>{f.name}</div>
              {!f.active&&<div style={{fontSize:11,color:C.mu,marginTop:1}}>Coming Soon</div>}
            </div>
            {f.active&&<div style={{fontSize:13,color:C.ac,fontWeight:600}}>{"\u2192"}</div>}
            {!f.active&&<div style={{fontSize:11,fontWeight:700,color:C.mu,background:C.bd,padding:"2px 6px",borderRadius:4,textTransform:"uppercase",letterSpacing:".3px"}}>Soon</div>}
          </div>))}
        </div>
      </div>
    </div>)}
    <style>{`@keyframes modalIn{from{opacity:0;transform:scale(.96) translateY(8px)}to{opacity:1;transform:scale(1) translateY(0)}}`}</style>
  </div>);
}


