/* ═══ PRINT STYLESHEET (injected once at app root) ═══ */
function PrintStyles(){return(<style>{`@media print{
  @page{size:A3 landscape;margin:10mm;}
  html,body{background:#fff !important;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  .no-print,.no-print *{display:none !important;}
  [style*="position: sticky"],[style*="position:sticky"]{position:static !important;top:auto !important;}
  [style*="position: fixed"],[style*="position:fixed"]{position:static !important;}
  [style*="overflow-x: auto"],[style*="overflowX"]{overflow:visible !important;}
  [style*="overflow-y: auto"],[style*="overflow:auto"]{overflow:visible !important;max-height:none !important;}
  [style*="min-height: 100vh"],[style*="minHeight"]{min-height:0 !important;}
  button{cursor:default !important;}
  table{page-break-inside:avoid;}
}`}</style>);}

function Card({title,children,accent,style:s,hideExport}){
  const ref=useRef(null);
  const [menu,setMenu]=useState(false);
  const [caps,setCaps]=useState({tbl:false,svg:false});
  useEffect(()=>{if(ref.current){setCaps({tbl:!!ref.current.querySelector("table"),svg:!!ref.current.querySelector("svg")});}},[children]);
  const fname=_safeName(title);
  const onCSV=e=>{e&&e.stopPropagation();const t=ref.current&&ref.current.querySelector("table");if(t)_dl(new Blob([_tableToCSV(t)],{type:"text/csv;charset=utf-8"}),fname+".csv");setMenu(false);};
  const onPNG=e=>{e&&e.stopPropagation();const sv=ref.current&&ref.current.querySelector("svg");if(sv)_svgToPNG(sv,2,b=>{if(b)_dl(b,fname+".png");});setMenu(false);};
  const onClick=e=>{e.stopPropagation();const only=caps.tbl&&!caps.svg?"csv":!caps.tbl&&caps.svg?"png":null;if(only==="csv")return onCSV();if(only==="png")return onPNG();if(caps.tbl||caps.svg)setMenu(m=>!m);};
  const showBtn=!hideExport&&(caps.tbl||caps.svg);
  return(<div style={{background:C.cd,borderRadius:C.r,border:"1px solid "+C.bd,padding:"12px 14px",boxShadow:C.sh,minWidth:0,overflow:"hidden",borderTop:accent?"2px solid "+accent:undefined,position:"relative",...s}}>
    {(title||showBtn)&&<div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8,gap:8}}>
      {title?<div style={{fontSize:14,fontWeight:600,color:C.md,textTransform:"uppercase",letterSpacing:".4px",flex:1,minWidth:0}}>{title}</div>:<div style={{flex:1}}/>}
      {showBtn&&<div className="no-print" style={{position:"relative",flexShrink:0}}>
        <button onClick={onClick} title="Download" style={{width:22,height:22,borderRadius:4,border:"1px solid "+C.bd,background:C.c2,color:C.mu,fontSize:14,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",lineHeight:1,padding:0}}>{"\u2913"}</button>
        {menu&&caps.tbl&&caps.svg&&<>
          <div onClick={()=>setMenu(false)} style={{position:"fixed",inset:0,zIndex:200}}/>
          <div style={{position:"absolute",right:0,top:"calc(100% + 4px)",background:C.cd,border:"1px solid "+C.bd,borderRadius:6,boxShadow:"0 4px 12px rgba(0,0,0,.12)",zIndex:201,minWidth:140,overflow:"hidden"}}>
            <button onClick={onCSV} style={{display:"block",width:"100%",padding:"7px 12px",border:"none",background:"transparent",textAlign:"left",fontSize:13,color:C.tx,cursor:"pointer",borderBottom:"1px solid "+C.bd}}>{"\u2913"} CSV (Table)</button>
            <button onClick={onPNG} style={{display:"block",width:"100%",padding:"7px 12px",border:"none",background:"transparent",textAlign:"left",fontSize:13,color:C.tx,cursor:"pointer"}}>{"\u2913"} PNG (Chart)</button>
          </div>
        </>}
      </div>}
    </div>}
    <div ref={ref}>{children}</div>
  </div>);
}

function DTable({cols,rows}){return(<div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}><thead><tr>{cols.map((c,i)=>(<th key={i} style={{textAlign:i===0?"left":"right",padding:"5px 8px",color:C.mu,fontWeight:600,borderBottom:"1px solid "+C.bd,fontSize:13}}>{c}</th>))}</tr></thead><tbody>{rows.map((row,ri)=>(<tr key={ri} style={{background:ri%2===0?"transparent":C.c2}}>{row.map((cell,ci)=>{const isS=typeof cell==="string"&&["OK","High","Low","Alert","Below","Monitor","Escalate","Open","Closed","Scrapped","Electrical","Mechanical","Instrumentation"].includes(cell);const stC=isS?(["OK","Closed"].includes(cell)?C.gn:["High","Low","Scrapped","Escalate","Below","Open"].includes(cell)?C.rd:["Electrical","Mechanical","Instrumentation"].includes(cell)?C.bl:C.am):null;return(<td key={ci} style={{padding:"6px 8px",borderBottom:"1px solid "+C.bd,textAlign:ci===0?"left":"right",color:stC||C.tx,fontWeight:stC?600:400}}>{isS?<span style={{padding:"2px 6px",borderRadius:999,fontSize:12,fontWeight:700,background:(stC||C.am)+"18",color:stC||C.am}}>{cell}</span>:cell}</td>);})}</tr>))}</tbody></table></div>);}

/* ═══ DRILLDOWN SUB-PANEL ═══ */
function SubDrill({title,items,onSelect,selected}){return(<div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:10}}>{items.map(it=>(<button key={it} onClick={e=>{e.stopPropagation();onSelect(it);}} style={{padding:"5px 12px",borderRadius:999,border:"1px solid "+(selected===it?C.aB:C.bd),background:selected===it?C.aL:C.c2,color:selected===it?C.ac:C.tx,fontSize:13,fontWeight:600,cursor:"pointer"}}>{it}</button>))}</div>);}

/* ═══ BUILD KPIS ═══ */
function buildKpis(sec,tab,stockSub,prodSub){
  /* prodSub factor — used to scale Production / Plan Compliance / FTQ / Scrap / Rework / NCM Hold KPI values */
  const _subFactor={"Master Compound":0.61,"Final Compound":0.39,"Passenger Radial":0.55,"LT Radial":0.25,"SCV Radial":0.20,"Belt Production":0.52,"Ply Production":0.48,"Sidewall Production":0.55,"Tread Production":0.45,"Inner Liner Production":1.0,"Rubberised Ply Production":0.55,"Rubberised Belt Production":0.45,"Production":1.0,"Overall":1.0,"Cap Strip Production":0.58,"Chafer Production":0.42}[prodSub]||1.0;
  /* prodSub quality offset — small +/- variation in FTQ / Scrap / Rework / NCM Hold per sub-category */
  const _subOffset=(()=>{
    const m={"Master Compound":0.4,"Final Compound":-0.4,"Passenger Radial":0.2,"LT Radial":-0.1,"SCV Radial":-0.3,"Belt Production":0.2,"Ply Production":-0.2,"Sidewall Production":0.1,"Tread Production":-0.2,"Inner Liner Production":0,"Rubberised Ply Production":0.1,"Rubberised Belt Production":-0.1,"Production":0,"Overall":0,"Cap Strip Production":0.3,"Chafer Production":-0.3};
    return m[prodSub]||0;
  })();
  const s=sec;
  if(tab==="P"){
    if(s.id==="MIX") return [
      {id:"oee",n:"OEE",v:s.oee,u:"%",tr:1.2,sp_:[89.5,90.1,90.8,91.5],sc_:C.ac,drillType:"mixOEE",drillData:MIX_OEE_DATA,subData:MIX_OEE_SUBDATA},
      {id:"prod",n:"Production",v:Math.round(468*_subFactor).toString(),u:"MT",tr:2.5,sp_:[Math.round(435*_subFactor),Math.round(447*_subFactor),Math.round(458*_subFactor),Math.round(468*_subFactor)],sc_:C.tl,drillType:"mixProd",prodSub:prodSub},
      {id:"dt",n:"Downtime",v:s.dt,u:"hrs",tr:-2.5,sp_:[3.5,3,2.5,2.1],sc_:C.rd,drillType:"downtime",drillData:[
        ["BD-ELEC","Banbury 1","Motor overload trip",2,45,"0.75"],["BD-MECH","Banbury 3","Ram cylinder seal leak",1,62,"1.03"],["BD-INST","Banbury 2","Thermocouple failure",1,18,"0.30"],
        ["SETUP","Banbury 4","SET UP & FTC",3,35,"0.58"],["SETUP","Banbury 1","SIZE CHANGE",2,28,"0.47"],
        ["PM","Banbury 5","PREV MAINTENANCE",1,120,"2.00"],["PROCESS","Banbury 2","PROCESS MAJOR ISSUE",1,25,"0.42"],
        ["UTILITY","Banbury Hall","POWER FAILURE",1,15,"0.25"],["OTHER","Open Mill","TECH. OTHERS",2,22,"0.37"]
      ]},
      {id:"comp",n:"Plan Compliance",v:(92+_subOffset*4).toFixed(1),u:"%",tr:-0.5,sp_:[94,93,92.5,(92+_subOffset*4)],sc_:C.bl}
    ];
    if(s.id==="TBM") return [
      {id:"oee",n:"OEE",v:s.oee,u:"%",tr:0.6,sp_:[80.5,81.2,81.8,82.4],sc_:C.ac,drillType:"mixOEE",drillData:TBM_OEE_DATA,subData:TBM_OEE_SUBDATA},
      {id:"prod",n:"Production",v:Math.round(1086*_subFactor).toLocaleString(),u:"nos",tr:1.5,sp_:[Math.round(1020*_subFactor),Math.round(1040*_subFactor),Math.round(1060*_subFactor),Math.round(1086*_subFactor)],sc_:C.tl,drillType:"tbmProd",secId:"TBM",prodSub:prodSub},
      {id:"dt",n:"Downtime",v:s.dt,u:"hrs",tr:-1.8,sp_:[7,6.5,6,5.8],sc_:C.rd,drillType:"downtime",drillData:[
        ["SETUP","VMI Max","SET UP & FTC",4,65,"1.08"],["SETUP","Stage 1","SIZE CHANGE",3,48,"0.80"],["MATERIAL","VMI Max","No tread",2,35,"0.58"],
        ["MATERIAL","Stage 2","NO CHAFER",2,28,"0.47"],["MATERIAL","VMI Exium","Defective tread",1,22,"0.37"],["MATERIAL","BJ Modules","Defective Capstrip",1,18,"0.30"],
        ["BD-MECH","Stage 1","Machine error",2,52,"0.87"],["PM","VMI Max","PREV MAINTENANCE",1,90,"1.50"],
        ["DEV","VMI Exium","DEVELOPMENT",1,30,"0.50"],["UTILITY","TBM Hall","POWER FAILURE",1,12,"0.20"],["OTHER","Stage 2","TECH. OTHERS",2,15,"0.25"]
      ]},
      {id:"comp",n:"Plan Compliance",v:(83+_subOffset*5).toFixed(1),u:"%",tr:-2.0,sp_:[87,85,84,(83+_subOffset*5)],sc_:C.bl}
    ];
    if(s.id==="CUR") return [
      {id:"oee",n:"OEE",v:s.oee,u:"%",tr:0.5,sp_:[86.8,87.2,87.8,88.1],sc_:C.ac,drillType:"mixOEE",drillData:CUR_OEE_DATA,subData:CUR_OEE_SUBDATA},
      {id:"prod",n:"Production",v:Math.round(9210*_subFactor).toLocaleString(),u:"nos",tr:1.8,sp_:[Math.round(8800*_subFactor),Math.round(8950*_subFactor),Math.round(9100*_subFactor),Math.round(9210*_subFactor)],sc_:C.tl,drillType:"tbmProd",secId:"CUR",prodSub:prodSub},
      {id:"dt",n:"Downtime",v:s.dt,u:"hrs",tr:-1.5,sp_:[4.5,4,3.5,3.2],sc_:C.rd,drillType:"downtime",drillData:[
        ["MOULD","Tredge 1","MOULD CHANGE",6,85,"1.42"],["MOULD","Tredge 3","MOULD CHANGE",4,72,"1.20"],["BLADDER","Tredge 2","BLADDER CHANGE",3,55,"0.92"],
        ["CLEANING","Tredge 4","ICE CLEANING",2,32,"0.53"],["SETUP","Tredge 1","FTC - FIRST TYRE CERTIFICATION",2,28,"0.47"],
        ["BD-MECH","Tredge 3","Hydraulic leak",1,45,"0.75"],["PM","Tredge 5","PREV MAINTENANCE",1,60,"1.00"],["OTHER","Tredge 6","TECH. OTHERS",1,12,"0.20"]
      ]},
      {id:"comp",n:"Plan Compliance",v:(89+_subOffset*4).toFixed(1),u:"%",tr:-0.8,sp_:[91,90,89.5,(89+_subOffset*4)],sc_:C.bl}
    ];
    /* Stock */
    const stkMachines={"4 Roll":["4 Roll #1","4 Roll #2"],"Extruder":["Duplex","Triplex","Quadraplex"],"3 Roll":["3 Roll #1","3 Roll #2"],"Cutter":["LTBC","HTBC"],"Slitter":["Slitter-1","Slitter-2"]};
    const stkOEE={"4 Roll":[[88.5,92,96.5,99.8],[86.3,90.5,95.8,99.6]],"Extruder":[[82.5,88.2,94,99.5],[86.8,90.8,96,99.6],[84.2,89,95.2,99.4]],"3 Roll":[[89.2,93,97,99.8],[87.5,91.5,96.2,99.7]],"Cutter":[[88,91.5,96.5,99.7],[85.3,89,95,99.5]],"Slitter":[[90.2,93.5,97.2,99.8],[88.8,92,96.5,99.7]]};
    const ms=stkMachines[stockSub]||[];
    const oeD=(stkOEE[stockSub]||[]).map((r,i)=>[ms[i]||"Machine "+(i+1),r[0],r[1],r[2],r[3]]);
    return [
      {id:"oee",n:"OEE",v:s.oee,u:"%",tr:0.8,sp_:[85.5,86.2,86.8,87.2],sc_:C.ac,drillType:"mixOEE",drillData:oeD,subData:STK_OEE_SUBDATA},
      {id:"prod",n:"Production",v:Math.round(1245*_subFactor).toLocaleString(),u:"units",tr:2.0,sp_:[Math.round(1150*_subFactor),Math.round(1180*_subFactor),Math.round(1210*_subFactor),Math.round(1245*_subFactor)],sc_:C.tl,drillType:"stkProd",stockSub:stockSub,prodSub:prodSub},
      {id:"dt",n:"Downtime",v:s.dt,u:"hrs",tr:-2.0,sp_:[4.5,4,3.6,3.4],sc_:C.rd,drillType:"downtime",drillData:[
        ["SETUP",ms[0]||stockSub,"SET UP & FTC",3,42,"0.70"],["SETUP",ms[0]||stockSub,"SIZE CHANGE",2,35,"0.58"],
        ["MATERIAL",ms[0]||stockSub,"No tread",1,22,"0.37"],["BD-MECH",ms[0]||stockSub,"Machine error",1,38,"0.63"],
        ["PM",ms[0]||stockSub,"PREV MAINTENANCE",1,80,"1.33"],["OTHER",ms[0]||stockSub,"TECH. OTHERS",2,18,"0.30"]
      ]},
      {id:"comp",n:"Plan Compliance",v:(88+_subOffset*4).toFixed(1),u:"%",tr:-1.2,sp_:[91,90,89,(88+_subOffset*4)],sc_:C.bl}
    ];
  }
  if(tab==="Q"){
    const skus=s.id==="MIX"?MIX_FINAL:TYRE_PCR.concat(TYRE_LTR.slice(0,2));
    const machines=s.id==="MIX"?["Banbury 1","Banbury 2","Banbury 3","Banbury 4","Banbury 5"]:s.id==="TBM"?["VMI Max","VMI Exium","BJ Modules","Stage 1","Stage 2"]:s.id==="CUR"?["Tredge 1","Tredge 2","Tredge 3","Tredge 4","Tredge 5","Tredge 6"]:({"4 Roll":["4 Roll #1","4 Roll #2"],"Extruder":["Duplex","Triplex","Quadraplex"],"3 Roll":["3 Roll #1","3 Roll #2"],"Cutter":["LTBC","HTBC"],"Slitter":["Slitter-1","Slitter-2"]}[stockSub]||[]);
    const reasons=s.id==="MIX"?["Viscosity NC","Off-Spec","Cure Rate NC","Contaminated"]:s.id==="TBM"?["Splice Open","Ply Wrinkle","Belt Edge","Bead Fault"]:s.id==="CUR"?["Bladder Mark","Flash","Porosity","Under-cure"]:["Width OOS","Gauge OOS","Surface","Bias Angle"];
    return [
      {id:"ftq",n:"FTQ",v:(100-s.sc-0.5+_subOffset).toFixed(1),u:"%",tr:0.3,sp_:[95,95.5,95.8,96],sc_:C.gn,drillType:"table",drillTitle:"Machine-wise FTQ",drillCols:["Machine","FTQ %","Defects","Top Defect"],drillRows:machines.slice(0,6).map((m,i)=>[m,(98-i*1.5).toFixed(1)+"%",3+i*3,reasons[i%reasons.length]])},
      {id:"ds",n:"Scrap",v:Math.round(s.sc*50*_subFactor),u:"nos",tr:-5,sp_:[Math.round(40*_subFactor),Math.round(35*_subFactor),Math.round(30*_subFactor),Math.round(25*_subFactor)],sc_:C.rd,drillType:"table",drillTitle:"Scrap Detail",drillCols:["SKU","Machine","Reason"],drillRows:skus.slice(0,8).map((sk,i)=>[sk,machines[i%machines.length],reasons[i%reasons.length]])},
      {id:"rw",n:"Rework",v:Math.round(s.sc*30*_subFactor),u:"nos",tr:-3,sp_:[Math.round(s.sc*38*_subFactor),Math.round(s.sc*34*_subFactor),Math.round(s.sc*32*_subFactor),Math.round(s.sc*30*_subFactor)],sc_:C.am,drillType:"table",drillTitle:"Rework Detail",drillCols:["SKU","Machine","Defect","Qty","Status"],drillRows:skus.slice(0,5).map((sk,i)=>[sk,machines[i%machines.length],reasons[i%reasons.length],3+i*2,i%2===0?"In progress":"Pending"])},
      {id:"ncm",n:"NCM Hold",v:Math.max(1,Math.round(5*_subFactor)).toString(),u:"batches",tr:-20,sp_:[Math.max(1,Math.round(8*_subFactor)),Math.max(1,Math.round(7*_subFactor)),Math.max(1,Math.round(6*_subFactor)),Math.max(1,Math.round(5*_subFactor))],sc_:C.am,drillType:"table",drillTitle:"NCM Hold Details",drillCols:["SKU","Batch","# Batches","Kgs","Hold Reason"],drillRows:skus.slice(0,5).map((sk,i)=>[sk,"B-"+(2840+i*3),1+Math.floor(i/2),250+i*80,reasons[i%reasons.length]])}
    ];
  }
  if(tab==="C"){
    const machines=s.id==="MIX"?["Banbury 1","Banbury 2","Banbury 3","Banbury 4","Banbury 5"]:s.id==="TBM"?["VMI Max","VMI Exium","BJ Modules","Stage 1","Stage 2"]:s.id==="CUR"?["Tredge 1","Tredge 2","Tredge 3","Tredge 4","Tredge 5","Tredge 6"]:({"4 Roll":["4 Roll #1","4 Roll #2"],"Extruder":["Duplex","Triplex","Quadraplex"],"3 Roll":["3 Roll #1","3 Roll #2"],"Cutter":["LTBC","HTBC"],"Slitter":["Slitter-1","Slitter-2"]}[stockSub]||[]);
    return [
      {id:"spc",n:"Specific Power",v:s.id==="MIX"?"312":s.id==="TBM"?"345":s.id==="CUR"?"380":"285",u:"kWh/MT",tr:-1.5,sp_:[330,325,318,312],sc_:C.tl,drillType:"table",drillTitle:"Machine-wise Specific Power",drillCols:["Machine","kWh","Output","Sp. Power","Target","Variance"],drillRows:machines.map((m,i)=>[m,280+i*25,(40+i*8)+" MT",((280+i*25)/(40+i*8)).toFixed(1),6.5,(((280+i*25)/(40+i*8))-6.5).toFixed(1)])},
      {id:"scrc",n:"Scrap Cost",v:+(s.sc*8).toFixed(1),u:"\u20B9L",tr:-3,sp_:[10,9,8.5,8],sc_:C.rd,drillType:null},
      {id:"bud",n:"Budget Util.",v:"85",u:"%",tr:0,sp_:[82,83,84,85],sc_:C.bl,drillType:"budget"}
    ];
  }
  if(tab==="M") return [
    {id:"ab",n:"Absenteeism",v:"3.2",u:"%",tr:-0.3,sp_:[4,3.5,3.3,3.2],sc_:C.gn,drillType:"table",drillTitle:"Area-wise Absenteeism",drillCols:["Area","Total","Present","Absent","Rate"],drillRows:(s.id==="MIX"?["Banbury Hall","Mill Area","Batch-off","Staff"]:s.id==="TBM"?["VMI Section","Stage 1/2","BJ Area","Staff"]:s.id==="CUR"?["Tredge 1-2","Tredge 3-4","Tredge 5-6","Staff"]:["Calender","Extruder","Cutter","Staff"]).map((a,i)=>[a,40+i*10,38+i*10,2,(2/(40+i*10)*100).toFixed(1)+"%"])},
    {id:"tq",n:"TQM Score",v:"3.8",u:"/5",tr:0.3,sp_:[3.2,3.4,3.6,3.8],sc_:C.pp,drillType:"table",drillTitle:"TQM by Pillar",drillCols:["Pillar","Score","Target","Gap"],drillRows:[["5S / Housekeeping",4.2,5,-0.8],["Kaizen / CI",3.5,5,-1.5],["QC Circle",3.8,5,-1.2],["Suggestion Scheme",3.6,5,-1.4],["PM Pillar",4.0,5,-1.0]]},
    {id:"sg",n:"Suggestions",v:"1.2",u:"/person",tr:0.2,sp_:[0.8,0.9,1,1.2],sc_:C.bl,drillType:"table",drillTitle:"Suggestion Status",drillCols:["Category","Submitted","Implemented","Pending","Savings \u20B9K"],drillRows:[["Quality",18,12,6,85],["Safety",12,10,2,42],["Productivity",15,8,7,120],["Cost Reduction",8,5,3,95]]},
    {id:"tr",n:"Training",v:"4.5",u:"hrs/m",tr:0.5,sp_:[3.5,3.8,4.2,4.5],sc_:C.tl,drillType:"table",drillTitle:"Training by Area",drillCols:["Area","Plan Hrs","Actual Hrs","Compliance %"],drillRows:(s.id==="MIX"?["Banbury Operators","Mill Operators","Batch-off","Supervisors"]:s.id==="TBM"?["VMI Operators","Stage Operators","BJ Operators","Supervisors"]:s.id==="CUR"?["Press Operators","Mould Team","Loader Operators","Supervisors"]:["Calender Ops","Extruder Ops","Cutter Ops","Supervisors"]).map((a,i)=>[a,5+i,(4+i*0.5).toFixed(1),((4+i*0.5)/(5+i)*100).toFixed(0)+"%"])}
  ];
  /* S - Safety */
  const sArea=s.id==="MIX"?"Banbury":s.id==="TBM"?"VMI Bay":s.id==="CUR"?"Tredge":"Calender";
  return [
    {id:"ri",n:"Reportable",v:"0",u:"nos",tr:0,sp_:[0,0,0,0],sc_:C.gn,drillType:"table",drillTitle:"Incident Log (90 Days)",drillCols:["Date","Type","Area","Description","Status"],drillRows:[["05-Apr","First Aid",sArea,"Minor burn from hot surface","Closed"],["18-Mar","Near Miss",sArea,"Material splash near operator","Closed"],["02-Mar","Near Miss",sArea,"Guard found missing on conveyor","Fixed"]]},
    {id:"fa",n:"First Aid",v:"3",u:"nos",tr:-25,sp_:[5,4,4,3],sc_:C.am,drillType:"table",drillTitle:"First Aid Details",drillCols:["Date","Area","Injury","Root Cause"],drillRows:[["05-Apr",sArea,"Minor burn","Hot surface contact"],["18-Mar",sArea,"Cut finger","Sharp edge on tool"],["02-Mar",sArea,"Eye irritation","Chemical splash"]]},
    {id:"nm",n:"Near Miss",v:"12",u:"nos",tr:25,sp_:[6,8,10,12],sc_:C.bl,drillType:"table",drillTitle:"Near Miss Categories",drillCols:["Category","Count","Share","Status"],drillRows:[["Unsafe Act",5,"38%","4 Closed, 1 Open"],["Unsafe Condition",4,"31%","3 Closed, 1 Open"],["Housekeeping",2,"15%","Closed"],["Electrical",1,"8%","Open"]]},
    {id:"sa",n:"Safety Audit",v:"94.2",u:"%",tr:1.2,sp_:[91,92.5,93.5,94.2],sc_:C.tl,drillType:"table",drillTitle:"Audit by Area",drillCols:["Area","Score","NC Major","NC Minor","Observations"],drillRows:(s.id==="MIX"?["Banbury Hall","Mill Area","Batch-off","Chemical Store"]:s.id==="TBM"?["VMI Bay","Stage 1/2 Bay","BJ Bay","Store Area"]:s.id==="CUR"?["Tredge 1-2","Tredge 3-4","Tredge 5-6","Mould Shop"]:["Calender Bay","Extruder Bay","Cutter Area","Store"]).map((a,i)=>[a,(96-i*1.5).toFixed(1)+"%",0,1+i,3+i*2])}
  ];
}

/* ═══ KPI CARD ═══ */
function KpiCard({kpi,isOpen,onToggle,onTrend,tyreType,plant}){
  const inv=/Scrap|Reject|Loss|Absent|First|Downtime|NCM/.test(kpi.n);
  const tc=kpi.tr>0?(inv?C.rd:C.gn):kpi.tr<0?(inv?C.gn:C.rd):C.mu;
  const v=tAdjust(kpi.v,kpi.n,tyreType,plant);
  const trendClick=e=>{e.stopPropagation();if(onTrend)onTrend(kpi);};
  return(<div onClick={onToggle} style={{background:C.cd,borderRadius:C.r,border:"1px solid "+(isOpen?C.ac+"88":C.bd),boxShadow:isOpen?"0 0 0 1px "+C.ac+"40, "+C.sh:C.sh,cursor:kpi.drillType?"pointer":"default",overflow:"hidden",transition:"border-color .2s"}}>
    <div style={{padding:"10px 12px"}}>
      <div style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".5px",marginBottom:4,display:"flex",justifyContent:"space-between",alignItems:"center",gap:6}}>
        <span style={{flex:1,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{kpi.n}</span>
        <div style={{display:"flex",alignItems:"center",gap:4,flexShrink:0}}>
          <button onClick={trendClick} title="View Trend (Daily / Monthly / Yearly)" style={{width:20,height:20,borderRadius:4,border:"1px solid "+C.bd,background:C.c2,color:C.mu,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",padding:0}}><TrendIcon size={11}/></button>
          {kpi.drillType&&<span title="Click card to drill down" style={{color:isOpen?C.ac:C.mu,transform:isOpen?"rotate(180deg)":"",transition:"transform .2s",fontSize:13}}>{"\u25BC"}</span>}
        </div>
      </div>
      <div style={{display:"flex",alignItems:"flex-end",justifyContent:"space-between"}}>
        <div style={{display:"flex",alignItems:"baseline",gap:3}}><span style={{fontSize:22,fontWeight:700,color:C.tx}}>{v}</span>{kpi.u&&<span style={{fontSize:12,color:C.mu}}>{kpi.u}</span>}</div>
        {kpi.sp_&&<Spark data={kpi.sp_} color={kpi.sc_||C.tl}/>}
      </div>
      {kpi.tr!=null&&kpi.tr!==0&&<div style={{fontSize:12,fontWeight:600,color:tc,marginTop:2}}>{kpi.tr>0?"\u25B2":"\u25BC"} {Math.abs(kpi.tr)}%</div>}
    </div>
  </div>);
}

/* ═══ DRILL PANEL ═══ */
function DrillPanel({kpi,sub,setSub,spcP,setSpcP}){
  const [machSearch,setMachSearch]=useState("");
  const [prodView,setProdView]=useState("machine");
  const [prodUnit,setProdUnit]=useState("");
  useEffect(()=>{setMachSearch("");setProdView("machine");setProdUnit("");},[kpi&&kpi.id]);
  if(!kpi||!kpi.drillType) return null;

  if(kpi.drillType==="mixOEE"){
    /* Data comes from kpi (per-section) with Mixing fallback */
    const oeData=kpi.drillData||MIX_OEE_DATA;
    const sd=kpi.subData||MIX_OEE_SUBDATA;
    const avail=sd.avail||{};
    const perf=sd.perf||{};
    const qual=sd.qual||{};
    const scrapByItem=sd.scrapByItem||{};
    /* Machine parameter spec — label, unit, normal range for alarm coloring */
    const PARAM_SPEC=[
      {k:"dropTemp",lbl:"Drop Temp",unit:"\u00B0C",lo:160,hi:170},
      {k:"tcu",lbl:"TCU",unit:"\u00B0C",lo:80,hi:92},
      {k:"rotorRpm",lbl:"Rotor",unit:"rpm",lo:28,hi:34},
      {k:"mixTime",lbl:"Mix Time",unit:"s",lo:240,hi:300},
      {k:"power",lbl:"Power",unit:"kW",lo:7.0,hi:8.5}
    ];

    const avSubs=["Breakdown","Setup & Adjustment","Startup","Tool Change"];
    const pfSubs=["Minor Stoppage","Reduced Speed"];
    const qlSubs=["Defect","Scrap"];

    /* Parse state: <Machine>:<Component>:<SubCategory>:<ItemCode> */
    const parts=(sub||"").split(":");
    const selMc=parts[0]||"";
    const selComp=parts[1]||"";
    const selSub=parts[2]||"";
    const selIc=parts[3]||"";

    /* Overall A/P/Q averages from the machine table */
    const avg=col=>+(oeData.reduce((a,r)=>a+r[col],0)/oeData.length).toFixed(1);
    const overall={a:avg(2),p:avg(3),q:avg(4)};
    const apqCol=(v,k)=>k==="a"?(v>=95?C.gn:v>=85?C.am:C.rd):k==="p"?(v>=95?C.gn:v>=90?C.am:C.rd):(v>=99?C.gn:v>=98?C.am:C.rd);

    const clickCell=(mc,comp)=>{if(selMc===mc&&selComp===comp&&!selSub)setSub("");else setSub(mc+":"+comp);};
    const clickSubCat=subc=>{if(selSub===subc)setSub(selMc+":"+selComp);else setSub(selMc+":"+selComp+":"+subc);};
    const noData=cat=>(<div style={{padding:"14px 16px",textAlign:"center",fontSize:12,color:C.mu,fontStyle:"italic",background:C.cd,borderRadius:6,border:"1px dashed "+C.bd,marginTop:8}}>No {cat} recorded for {selMc} in this period.</div>);

    return(<Card title="Machine-wise OEE Breakdown" accent={C.ac}>

      {/* Overall A/P/Q tiles — plant-level summary inside this drill */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10,marginBottom:14}}>
        {[
          {l:"Availability",v:overall.a,k:"a",sub:"Across "+oeData.length+" Banbury machines"},
          {l:"Performance",v:overall.p,k:"p",sub:"Plant average for Mixing section"},
          {l:"Quality",v:overall.q,k:"q",sub:"FTQ \u00B7 Mixing section"}
        ].map(t=>{const col=apqCol(t.v,t.k);return(<div key={t.l} style={{padding:"10px 14px",background:col+"10",borderRadius:8,border:"1px solid "+col+"33",borderLeft:"3px solid "+col}}>
          <div style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".4px"}}>{t.l}</div>
          <div style={{display:"flex",alignItems:"baseline",gap:3,marginTop:2}}>
            <span style={{fontSize:23,fontWeight:700,color:col}}>{t.v}</span>
            <span style={{fontSize:13,fontWeight:600,color:col}}>%</span>
          </div>
          <div style={{fontSize:11,color:C.mu,marginTop:1}}>{t.sub}</div>
        </div>);})}
      </div>

      {/* Machine search */}
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
        <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>Search Machine</span>
        <input type="text" value={machSearch} onChange={e=>setMachSearch(e.target.value)} placeholder="e.g. Banbury 2" style={{padding:"5px 10px",border:"1px solid "+C.bd,borderRadius:6,fontSize:12,outline:"none",width:200,background:C.cd,color:C.tx,fontFamily:"inherit"}}/>
        {machSearch&&<button onClick={()=>setMachSearch("")} style={{padding:"4px 10px",border:"1px solid "+C.bd,borderRadius:6,background:C.c2,fontSize:11,cursor:"pointer",color:C.mu}}>Clear</button>}
      </div>

      {/* Machine table \u2014 A/P/Q cells clickable, OEE plain */}
      <div style={{maxHeight:340,overflowY:"auto",overflowX:"auto",border:"1px solid "+C.bd,borderRadius:6}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}>
        <thead style={{position:"sticky",top:0,background:C.cd,zIndex:1}}><tr>{["Machine","OEE %","Availability %","Performance %","Quality %"].map((c,i)=>(<th key={i} style={{textAlign:i===0?"left":"right",padding:"7px 10px",color:C.mu,fontWeight:600,borderBottom:"1px solid "+C.bd,fontSize:13,background:C.cd}}>{c}</th>))}</tr></thead>
        <tbody>{(()=>{const filtered=oeData.filter(r=>!machSearch||String(r[0]).toLowerCase().includes(machSearch.toLowerCase()));if(!filtered.length)return(<tr><td colSpan={5} style={{padding:"24px 10px",textAlign:"center",color:C.mu,fontSize:13,fontStyle:"italic"}}>No machines match "{machSearch}"</td></tr>);return filtered.map((r,ri)=>{
          const mc=r[0];
          const isMcSel=selMc===mc;
          return(<tr key={ri} style={{background:isMcSel?C.aL:(ri%2===0?"transparent":C.c2)}}>
            <td style={{padding:"9px 10px",borderBottom:"1px solid "+C.bd,fontWeight:isMcSel?700:600,color:isMcSel?C.ac:C.tx}}>{mc}</td>
            <td style={{padding:"9px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",color:C.tx,fontWeight:600}}>{r[1]}%</td>
            {[{col:2,k:"a",comp:"Availability"},{col:3,k:"p",comp:"Performance"},{col:4,k:"q",comp:"Quality"}].map(({col,k,comp})=>{
              const v=r[col];
              const c=apqCol(v,k);
              const cellSel=isMcSel&&selComp===comp;
              return(<td key={comp} onClick={()=>clickCell(mc,comp)} title={"Drill into "+mc+" \u2014 "+comp} style={{padding:"9px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",cursor:"pointer",color:cellSel?"#fff":c,fontWeight:700,background:cellSel?c:"transparent",transition:"background .15s"}}
                onMouseOver={e=>{if(!cellSel)e.currentTarget.style.background=c+"15";}}
                onMouseOut={e=>{if(!cellSel)e.currentTarget.style.background="transparent";}}>
                {v}%<span style={{fontSize:11,marginLeft:5,opacity:cellSel?0.9:0.6}}>{"\u25B8"}</span>
              </td>);
            })}
          </tr>);
        });})()}</tbody>
      </table></div>
      {!selMc&&<div style={{fontSize:12,color:C.am,marginTop:8,fontWeight:500}}>{"\u25B8"} Click an Availability, Performance, or Quality cell on any row to drill into that machine</div>}

      {/* Per-machine drill panel */}
      {selMc&&selComp&&(()=>{
        const subs=selComp==="Availability"?avSubs:selComp==="Performance"?pfSubs:qlSubs;
        const compAcc=selComp==="Availability"?C.bl:selComp==="Performance"?C.am:C.tl;
        return(<div style={{marginTop:14,padding:"12px 14px",background:C.c2,borderRadius:8,border:"1px solid "+C.bd,borderLeft:"3px solid "+compAcc,animation:"fadeIn .2s ease"}}>
          <Breadcrumb path={selIc?["OE",selMc,selComp,selSub,selIc,"Production IDs"]:selSub?["OE",selMc,selComp,selSub]:["OE",selMc,selComp]}/>
          <div style={{fontSize:13,fontWeight:700,color:compAcc,textTransform:"uppercase",letterSpacing:".4px",marginBottom:6,marginTop:4}}>{selMc} {"\u2014"} {selComp} Sub-categories</div>
          <SubDrill items={subs} selected={selSub} onSelect={clickSubCat}/>

          {/* Availability */}
          {selComp==="Availability"&&<>
            {selSub==="Breakdown"&&(()=>{const rows=avail.Breakdown.filter(r=>r[0]===selMc);return rows.length?<DTable cols={["Machine","Type","Reason","Duration"]} rows={rows}/>:noData("breakdown events");})()}
            {selSub==="Setup & Adjustment"&&(()=>{const rows=avail["Setup & Adjustment"].filter(r=>r[0]===selMc);return rows.length?<DTable cols={["Machine","Changeover Type","Time (min)"]} rows={rows}/>:noData("setup/adjustment events");})()}
            {selSub==="Startup"&&(()=>{const rows=avail.Startup.filter(r=>r[0]===selMc);return rows.length?<DTable cols={["Machine","Event","Time (min)"]} rows={rows}/>:noData("startup events");})()}
            {selSub==="Tool Change"&&(()=>{const rows=avail["Tool Change"].filter(r=>r[0]===selMc);return rows.length?<DTable cols={["Machine","Tool Changed","Time (min)"]} rows={rows}/>:noData("tool change events");})()}
          </>}

          {/* Performance */}
          {selComp==="Performance"&&<>
            {selSub==="Minor Stoppage"&&(()=>{const rows=perf["Minor Stoppage"].filter(r=>r[0]===selMc);return rows.length?<DTable cols={["Machine","Reason","Duration","SKU"]} rows={rows}/>:noData("minor stoppages");})()}
            {selSub==="Reduced Speed"&&(()=>{const rows=perf["Reduced Speed"].filter(r=>r[0]===selMc);return rows.length?<DTable cols={["Machine","Reason","Duration","SKU"]} rows={rows}/>:noData("reduced speed events");})()}
          </>}

          {/* Quality — Defect simple, Scrap retains item code + production ID traceability */}
          {selComp==="Quality"&&<>
            {selSub==="Defect"&&(()=>{const rows=qual.Defect.filter(r=>r[2]===selMc);return rows.length?<DTable cols={["SKU","Defect Reason","Machine","Qty"]} rows={rows}/>:noData("defects");})()}
            {selSub==="Scrap"&&(()=>{
              const sRows=qual.Scrap.filter(r=>r[2]===selMc);
              if(!sRows.length)return noData("scrap events");
              return(<>
                <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}>
                  <thead><tr>{["SKU / Item Code","Scrap Reason","Machine","Qty (kg)",""].map((c,i)=>(<th key={i} style={{textAlign:i<=2?"left":i===3?"right":"center",padding:"6px 8px",color:C.mu,fontWeight:600,borderBottom:"1px solid "+C.bd,fontSize:13}}>{c}</th>))}</tr></thead>
                  <tbody>{sRows.map((r,ri)=>{const ic=r[0],sIc=selIc===ic,can=!!scrapByItem[ic];return(<tr key={ri} onClick={()=>can&&setSub(sIc?selMc+":Quality:Scrap":selMc+":Quality:Scrap:"+ic)} style={{background:sIc?C.aL:(ri%2===0?"transparent":C.cd),cursor:can?"pointer":"default"}}>
                    <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,fontWeight:sIc?700:500,color:sIc?C.ac:C.tx}}>{ic}{can&&<span style={{fontSize:11,color:C.am,marginLeft:6}}>{"\u25B8"}</span>}</td>
                    <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd}}>{r[1]}</td>
                    <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd}}>{r[2]}</td>
                    <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:700,color:C.rd}}>{r[3]}</td>
                    <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,textAlign:"center",fontSize:11,color:can?C.am:C.mu,fontWeight:600}}>{can?"Trace \u25B8":"\u2014"}</td>
                  </tr>);})}</tbody>
                </table></div>
                {selIc&&scrapByItem[selIc]&&(()=>{
                  const ic=selIc;
                  const tRows=scrapByItem[ic];
                  const onTrace=()=>{
                    const today=new Date().toISOString().slice(0,10);
                    const hdr=["Item Code","Production ID","Produced Quantity (kg)","Scrap Quantity (kg)","Produced By","Production Date & Time","Machine Name","Shift","Batch/Lot Details","Scrap Reason","Drop Temp (\u00B0C)","TCU (\u00B0C)","Rotor (rpm)","Mix Time (s)","Power (kW)","Alarm Parameter"];
                    const esc=v=>{const s=String(v==null?"":v);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};
                    const csv=[hdr.map(esc).join(","),...tRows.map(r=>{const p=r.params||{};const a=r.alarm?(PARAM_SPEC.find(x=>x.k===r.alarm)||{}).lbl:"";return[ic,r.pid,r.produced,r.scrap,r.operator,r.dt,r.machine,r.shift,r.batch,r.reason,p.dropTemp,p.tcu,p.rotorRpm,p.mixTime,p.power,a].map(esc).join(",");})].join("\n");
                    _dl(new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8"}),"traceability_"+ic+"_"+today+".csv");
                  };
                  return(<div style={{marginTop:14,padding:14,background:C.aL,borderRadius:8,border:"1px solid "+C.aB,animation:"fadeIn .2s ease"}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,gap:12,flexWrap:"wrap"}}>
                      <Breadcrumb path={["OE",selMc,"Quality","Scrap",ic,"Production IDs"]}/>
                      <button onClick={onTrace} title={"Downloads full traceability CSV for all "+tRows.length+" production IDs"} style={{padding:"8px 14px",fontSize:13,fontWeight:700,border:"none",borderRadius:6,background:C.ac,color:"#fff",cursor:"pointer",display:"flex",alignItems:"center",gap:6,whiteSpace:"nowrap",boxShadow:"0 2px 6px "+C.ac+"40"}}>{"\u2913"} Download Traceability Report</button>
                    </div>
                    <div style={{overflowX:"auto",background:C.cd,borderRadius:6,border:"1px solid "+C.bd}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                      <thead><tr style={{background:C.c2}}>{["Production ID","Shift","Operator","Produced (kg)","Scrap (kg)","Date & Time","Machine Parameters"].map((c,i)=>(<th key={i} style={{textAlign:i===3||i===4?"right":"left",padding:"7px 8px",color:C.md,fontWeight:700,borderBottom:"1px solid "+C.bd,fontSize:12,textTransform:"uppercase",letterSpacing:".3px"}}>{c}</th>))}</tr></thead>
                      <tbody>{tRows.map((r,i)=>(<tr key={i} style={{background:i%2===0?C.cd:C.c2,verticalAlign:"top"}}>
                        <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,fontWeight:700,color:C.tx,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12}}>{r.pid}</td>
                        <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd}}><span style={{padding:"2px 7px",borderRadius:999,fontSize:11,fontWeight:700,background:r.shift==="A"?C.bl+"18":r.shift==="B"?C.am+"18":C.pp+"18",color:r.shift==="A"?C.bl:r.shift==="B"?C.am:C.pp}}>{r.shift}</span></td>
                        <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,fontSize:12}}>{r.operator}</td>
                        <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,textAlign:"right"}}>{r.produced}</td>
                        <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:700,color:C.rd}}>{r.scrap}</td>
                        <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,fontSize:12,color:C.mu}}>{r.dt}</td>
                        <td style={{padding:"7px 8px",borderBottom:"1px solid "+C.bd,fontSize:11}}>
                          <div style={{display:"flex",flexWrap:"wrap",gap:"4px 8px",alignItems:"center"}}>{PARAM_SPEC.map(p=>{const v=(r.params||{})[p.k];if(v==null)return null;const isAlarm=r.alarm===p.k;return(<span key={p.k} title={p.lbl+(isAlarm?" \u2014 OUT OF RANGE ("+p.lo+"\u2013"+p.hi+" "+p.unit+")":" (normal "+p.lo+"\u2013"+p.hi+" "+p.unit+")")} style={{display:"inline-flex",alignItems:"baseline",gap:3,padding:isAlarm?"1px 6px":0,background:isAlarm?C.rd+"15":"transparent",borderRadius:4,border:isAlarm?"1px solid "+C.rd+"40":"none"}}>
                            <span style={{color:C.mu,fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>{p.lbl}</span>
                            <span style={{color:isAlarm?C.rd:C.tx,fontWeight:isAlarm?700:600,fontSize:12,fontFamily:"ui-monospace,Menlo,monospace"}}>{v}{p.unit}</span>
                            {isAlarm&&<span style={{color:C.rd,fontSize:10,fontWeight:700}}>{"\u26A0"}</span>}
                          </span>);})}</div>
                        </td>
                      </tr>))}</tbody>
                    </table></div>
                  </div>);
                })()}
              </>);
            })()}
          </>}
        </div>);
      })()}
    </Card>);
  }

  if(kpi.drillType==="mixProd"){
    const activeCat=kpi.prodSub||"Master Compound";
    /* Master compounds: smaller volumes, MIX_MASTER list, 1.80 MT/batch, Banbury 1\u20133 */
    const masterRows=MIX_MASTER.slice(0,6).map((cc,i)=>{
      const plan=30+i*5;
      const act=Math.round(plan*(0.88+i*0.02));
      const mtPerBatch=1.80;
      const bPlan=Math.round(plan/mtPerBatch);
      const bAct=Math.round(act/mtPerBatch);
      const achievement=((act/plan)*100).toFixed(1)+"%";
      const mc=["Banbury 1","Banbury 2","Banbury 3","Banbury 1","Banbury 2","Banbury 3"][i]||("Banbury "+((i%3)+1));
      return{type:"Master",mc,cc,plan,act,bPlan,bAct,achievement};
    });
    /* Final compounds: MIX_FINAL list, 1.95 MT/batch, Banbury 1\u20135 */
    const finalRows=MIX_FINAL.slice(0,8).map((cc,i)=>{
      const plan=25+i*6;
      const act=Math.round(plan*(0.85+i*0.02));
      const mtPerBatch=1.95;
      const bPlan=Math.round(plan/mtPerBatch);
      const bAct=Math.round(act/mtPerBatch);
      const achievement=((act/plan)*100).toFixed(1)+"%";
      const mc=["Banbury 1","Banbury 2","Banbury 3","Banbury 4","Banbury 5","Banbury 1","Banbury 2","Banbury 3"][i]||("Banbury "+((i%5)+1));
      return{type:"Final",mc,cc,plan,act,bPlan,bAct,achievement};
    });
    /* Pick rows by section-level sub-category */
    const detailRows=activeCat==="Master Compound"?masterRows:finalRows;
    /* Aggregations for View by toggle */
    const machAgg={};
    detailRows.forEach(r=>{if(!machAgg[r.mc])machAgg[r.mc]={mc:r.mc,plan:0,act:0,bPlan:0,bAct:0,ccs:0};machAgg[r.mc].plan+=r.plan;machAgg[r.mc].act+=r.act;machAgg[r.mc].bPlan+=r.bPlan;machAgg[r.mc].bAct+=r.bAct;machAgg[r.mc].ccs++;});
    const machRows=Object.values(machAgg).map(r=>({...r,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    const ccAgg={};
    detailRows.forEach(r=>{if(!ccAgg[r.cc])ccAgg[r.cc]={cc:r.cc,type:r.type,plan:0,act:0,bPlan:0,bAct:0,machs:new Set()};ccAgg[r.cc].plan+=r.plan;ccAgg[r.cc].act+=r.act;ccAgg[r.cc].bPlan+=r.bPlan;ccAgg[r.cc].bAct+=r.bAct;ccAgg[r.cc].machs.add(r.mc);});
    const ccRows=Object.values(ccAgg).map(r=>({...r,machCount:r.machs.size,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    /* Pick rows based on prodView */
    const rawRows=prodView==="machine"?machRows:prodView==="sku"?ccRows:detailRows;
    const filtered=rawRows.filter(r=>{if(!machSearch)return true;if(prodView==="sku")return [...r.machs].some(m=>m.toLowerCase().includes(machSearch.toLowerCase()));return r.mc.toLowerCase().includes(machSearch.toLowerCase());});
    const activeUnit=prodUnit||"MT";
    /* Column set depends on selected unit AND view */
    const planCol=activeUnit==="Batches"?"Batches Plan":"Planned (MT)";
    const actCol=activeUnit==="Batches"?"Batches Actual":"Actual (MT)";
    const cols=prodView==="machine"?["Machine","Compounds",planCol,actCol,"Achievement"]:prodView==="sku"?["Item Code","Machines",planCol,actCol,"Achievement"]:["Machine","Item Code",planCol,actCol,"Achievement"];
    return(<Card title={"Mixing \u2014 "+activeCat+" Production"} accent={C.tl}>
      {/* View by + Unit toggles */}
      <div style={{display:"flex",alignItems:"center",gap:14,marginTop:4,marginBottom:8,flexWrap:"wrap"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>View by</span>
          <div style={{display:"flex",gap:4}}>
            {[{k:"machine",l:"Machine"},{k:"sku",l:"SKU"},{k:"both",l:"Machine + SKU"}].map(o=>{const a=prodView===o.k;return(<button key={o.k} onClick={()=>setProdView(o.k)} style={{padding:"5px 12px",borderRadius:6,border:"1px solid "+(a?C.aB:C.bd),background:a?C.aL:C.c2,color:a?C.ac:C.tx,fontSize:12,fontWeight:a?700:500,cursor:"pointer"}}>{o.l}</button>);})}
          </div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>Unit</span>
          <div style={{display:"flex",gap:4}}>
            {[{k:"MT",l:"MT"},{k:"Batches",l:"Batches"}].map(o=>{const a=activeUnit===o.k;return(<button key={o.k} onClick={()=>setProdUnit(o.k)} style={{padding:"5px 12px",borderRadius:6,border:"1px solid "+(a?C.aB:C.bd),background:a?C.aL:C.c2,color:a?C.ac:C.tx,fontSize:12,fontWeight:a?700:500,cursor:"pointer"}}>{o.l}</button>);})}
          </div>
        </div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
        <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>Search Machine</span>
        <input type="text" value={machSearch} onChange={e=>setMachSearch(e.target.value)} placeholder="e.g. Banbury 2" style={{padding:"5px 10px",border:"1px solid "+C.bd,borderRadius:6,fontSize:12,outline:"none",width:200,background:C.cd,color:C.tx,fontFamily:"inherit"}}/>
        {machSearch&&<button onClick={()=>setMachSearch("")} style={{padding:"4px 10px",border:"1px solid "+C.bd,borderRadius:6,background:C.c2,fontSize:11,cursor:"pointer",color:C.mu}}>Clear</button>}
        <span style={{marginLeft:"auto",fontSize:11,color:C.mu}}>{filtered.length} of {rawRows.length} rows in {activeCat}</span>
      </div>
      <div style={{maxHeight:340,overflowY:"auto",overflowX:"auto",border:"1px solid "+C.bd,borderRadius:6}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
        <thead style={{position:"sticky",top:0,background:C.cd,zIndex:1}}><tr>{cols.map((c,i)=>{const lastIdxLeft=prodView==="machine"?0:1;return(<th key={i} style={{textAlign:i<=lastIdxLeft?"left":"right",padding:"7px 10px",color:C.mu,fontWeight:600,borderBottom:"1px solid "+C.bd,fontSize:12,background:C.cd,textTransform:"uppercase",letterSpacing:".3px"}}>{c}</th>);})}</tr></thead>
        <tbody>{filtered.length===0?(<tr><td colSpan={cols.length} style={{padding:"24px 10px",textAlign:"center",color:C.mu,fontSize:13,fontStyle:"italic"}}>No rows match "{machSearch}"</td></tr>):filtered.map((r,i)=>{
          const aNum=parseFloat(r.achievement);
          const aCol=aNum>=100?C.gn:aNum>=95?C.am:C.rd;
          const planVal=activeUnit==="Batches"?r.bPlan:r.plan;
          const actVal=activeUnit==="Batches"?r.bAct:r.act;
          return(<tr key={i} style={{background:i%2===0?"transparent":C.c2}}>
            {prodView==="machine"&&<><td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.tx}}>{r.mc}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",color:C.mu}}>{r.ccs}</td></>}
            {prodView==="sku"&&<><td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12,fontWeight:600}}>{r.cc}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",color:C.mu}}>{r.machCount}</td></>}
            {prodView==="both"&&<><td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.tx}}>{r.mc}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12,fontWeight:600}}>{r.cc}</td></>}
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right"}}>{planVal}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:600,color:C.tx}}>{actVal}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:700,color:aCol}}>{r.achievement}</td>
          </tr>);
        })}</tbody>
      </table></div>
    </Card>);
  }

  if(kpi.drillType==="tbmProd"){
    const isCur=kpi.secId==="CUR";
    const subSections=isCur?["Tredge 1","Tredge 2","Tredge 3","Tredge 4","Tredge 5","Tredge 6"]:[];
    const machines=isCur?["Press 1","Press 2","Press 3","Press 4","Press 5"]:["VMI Max","VMI Exium","BJ Modules","Stage 1","Stage 2"];
    const activeCat=kpi.prodSub||"Passenger Radial";
    const skuByCat={"Passenger Radial":TYRE_PCR.slice(0,4),"LT Radial":TYRE_LTR.slice(0,3),"SCV Radial":TYRE_SCV.slice(0,3)};
    const allSKUs=skuByCat[activeCat]||[];
    const base=isCur?80:42;
    const step=isCur?10:8;
    const ratio=isCur?0.88:0.82;
    /* Build detail rows */
    const detailRows=[];
    if(isCur){
      /* Curing: each (Tredge \u00D7 Press) position runs one SKU, cycling through allSKUs */
      subSections.forEach((sub,si)=>{
        machines.forEach((mc,mi)=>{
          if(allSKUs.length===0)return;
          const sku=allSKUs[(si*machines.length+mi)%allSKUs.length];
          const plan=base+si*step+mi*6;
          const act=Math.round(plan*(ratio+si*0.005+mi*0.005));
          detailRows.push({sub,mc,sku,plan,act});
        });
      });
    }else{
      /* TBM: machine \u00D7 SKU detail (original) */
      const skuPerMc=Math.max(1,Math.ceil(allSKUs.length/machines.length));
      machines.forEach((mc,i)=>{
        for(let j=0;j<skuPerMc;j++){
          const idx=i*skuPerMc+j;
          if(allSKUs.length===0)break;
          const sku=allSKUs[idx%allSKUs.length];
          const plan=base+i*step+j*12;
          const act=Math.round(plan*(ratio+i*0.015+j*0.008));
          detailRows.push({mc,sku,plan,act});
        }
      });
    }
    /* Aggregate by machine. For Curing each row is a unique (Tredge,Press) position */
    const machAgg={};
    detailRows.forEach(r=>{
      const key=isCur?(r.sub+"|"+r.mc):r.mc;
      if(!machAgg[key])machAgg[key]={sub:r.sub,mc:r.mc,plan:0,act:0,skus:0};
      machAgg[key].plan+=r.plan;machAgg[key].act+=r.act;machAgg[key].skus++;
    });
    const machRows=Object.values(machAgg).map(r=>({...r,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    /* Aggregate by SKU */
    const skuAgg={};
    detailRows.forEach(r=>{
      if(!skuAgg[r.sku])skuAgg[r.sku]={sku:r.sku,plan:0,act:0,machs:new Set()};
      skuAgg[r.sku].plan+=r.plan;skuAgg[r.sku].act+=r.act;
      skuAgg[r.sku].machs.add(isCur?(r.sub+"|"+r.mc):r.mc);
    });
    const skuRows=Object.values(skuAgg).map(r=>({...r,machCount:r.machs.size,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    const bothRows=detailRows.map(r=>({...r,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    const rawRows=prodView==="machine"?machRows:prodView==="sku"?skuRows:bothRows;
    const filtered=rawRows.filter(r=>{
      if(!machSearch)return true;
      const s=machSearch.toLowerCase();
      if(prodView==="sku")return [...r.machs].some(m=>m.toLowerCase().includes(s));
      return (r.mc&&r.mc.toLowerCase().includes(s))||(r.sub&&r.sub.toLowerCase().includes(s));
    });
    const title=isCur?"Curing \u2014 "+activeCat+" Production":"Tyre Building \u2014 "+activeCat+" Production";
    /* Column config per view */
    const colCfg=isCur?(prodView==="machine"?["Sub-section","Machine","SKUs","Planned (nos)","Actual (nos)","Achievement"]:prodView==="sku"?["Item Code (SKU)","Positions","Planned (nos)","Actual (nos)","Achievement"]:["Sub-section","Machine","Item Code (SKU)","Planned (nos)","Actual (nos)","Achievement"]):(prodView==="machine"?["Machine","SKUs","Planned (nos)","Actual (nos)","Achievement"]:prodView==="sku"?["Item Code (SKU)","Machines","Planned (nos)","Actual (nos)","Achievement"]:["Machine","Item Code (SKU)","Planned (nos)","Actual (nos)","Achievement"]);
    /* Number of left-aligned columns */
    const leftCount=isCur?(prodView==="machine"?2:prodView==="sku"?1:3):(prodView==="machine"?1:prodView==="sku"?1:2);
    return(<Card title={title} accent={C.tl}>
      {/* View toggle */}
      <div style={{display:"flex",alignItems:"center",gap:10,marginTop:4,marginBottom:8,flexWrap:"wrap"}}>
        <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>View by</span>
        <div style={{display:"flex",gap:4}}>
          {[{k:"machine",l:"Machine"},{k:"sku",l:"SKU"},{k:"both",l:"Machine + SKU"}].map(o=>{const a=prodView===o.k;return(<button key={o.k} onClick={()=>setProdView(o.k)} style={{padding:"5px 12px",borderRadius:6,border:"1px solid "+(a?C.aB:C.bd),background:a?C.aL:C.c2,color:a?C.ac:C.tx,fontSize:12,fontWeight:a?700:500,cursor:"pointer"}}>{o.l}</button>);})}
        </div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
        <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>Search</span>
        <input type="text" value={machSearch} onChange={e=>setMachSearch(e.target.value)} placeholder={isCur?"e.g. Tredge 3 or Press 2":"e.g. VMI Max"} style={{padding:"5px 10px",border:"1px solid "+C.bd,borderRadius:6,fontSize:12,outline:"none",width:220,background:C.cd,color:C.tx,fontFamily:"inherit"}}/>
        {machSearch&&<button onClick={()=>setMachSearch("")} style={{padding:"4px 10px",border:"1px solid "+C.bd,borderRadius:6,background:C.c2,fontSize:11,cursor:"pointer",color:C.mu}}>Clear</button>}
        <span style={{marginLeft:"auto",fontSize:11,color:C.mu}}>{filtered.length} of {rawRows.length} rows</span>
      </div>
      <div style={{maxHeight:340,overflowY:"auto",overflowX:"auto",border:"1px solid "+C.bd,borderRadius:6}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
        <thead style={{position:"sticky",top:0,background:C.cd,zIndex:1}}><tr>{colCfg.map((c,i)=>(<th key={i} style={{textAlign:i<leftCount?"left":"right",padding:"7px 10px",color:C.mu,fontWeight:600,borderBottom:"1px solid "+C.bd,fontSize:12,background:C.cd,textTransform:"uppercase",letterSpacing:".3px"}}>{c}</th>))}</tr></thead>
        <tbody>{filtered.length===0?(<tr><td colSpan={colCfg.length} style={{padding:"24px 10px",textAlign:"center",color:C.mu,fontSize:13,fontStyle:"italic"}}>No rows match "{machSearch}"</td></tr>):filtered.map((r,i)=>{
          const aNum=parseFloat(r.achievement);
          const aCol=aNum>=100?C.gn:aNum>=95?C.am:C.rd;
          return(<tr key={i} style={{background:i%2===0?"transparent":C.c2}}>
            {prodView==="machine"&&<>
              {isCur&&<td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.bl,fontSize:12}}>{r.sub}</td>}
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.tx}}>{r.mc}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",color:C.mu}}>{r.skus}</td></>}
            {prodView==="sku"&&<><td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12,fontWeight:600}}>{r.sku}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",color:C.mu}}>{r.machCount}</td></>}
            {prodView==="both"&&<>
              {isCur&&<td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.bl,fontSize:12}}>{r.sub}</td>}
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.tx}}>{r.mc}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12,fontWeight:600}}>{r.sku}</td></>}
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right"}}>{r.plan}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:600,color:C.tx}}>{r.act}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:700,color:aCol}}>{r.achievement}</td>
          </tr>);
        })}</tbody>
      </table></div>
    </Card>);
  }

  if(kpi.drillType==="stkProd"){
    const stockSub=kpi.stockSub||"4 Roll";
    const stkMachines={"4 Roll":["4 Roll #1","4 Roll #2"],"Extruder":["Duplex","Triplex","Quadraplex"],"3 Roll":["3 Roll #1","3 Roll #2"],"Cutter":["LTBC","HTBC"],"Slitter":["Slitter-1","Slitter-2"]};
    const machines=stkMachines[stockSub]||["Machine 1","Machine 2"];
    const catMap={"4 Roll":["Overall","Rubberised Ply Production","Rubberised Belt Production"],"Extruder":["Overall","Sidewall Production","Tread Production"],"3 Roll":["Overall","Inner Liner Production"],"Cutter":["Overall","Ply Production","Belt Production"],"Slitter":["Overall","Cap Strip Production","Chafer Production"]};
    const cats=catMap[stockSub]||["Overall"];
    const activeCat=kpi.prodSub||cats[0];
    const skuMap={
      "4 Roll":{"Rubberised Ply Production":["RubPly-PCR-001","RubPly-PCR-002"],"Rubberised Belt Production":["RubBelt-PCR-001","RubBelt-LTR-001"]},
      "Extruder":{"Sidewall Production":["Sidewall-PCR-001","Sidewall-LTR-001"],"Tread Production":["Tread-PCR-001","Tread-PCR-002"]},
      "3 Roll":{"Inner Liner Production":["I.Liner-PCR-001","I.Liner-LTR-001"]},
      "Cutter":{"Ply Production":["Ply-PCR-001","Ply-PCR-002"],"Belt Production":["Belt-PCR-001"]},
      "Slitter":{"Cap Strip Production":["Capstrip-PCR-001","Capstrip-PCR-002"],"Chafer Production":["Chafer-PCR-001"]}
    };
    /* "Overall" = the sub-section total → union of every product type's SKUs. */
    const _allSkus=Object.values(skuMap[stockSub]||{}).flat();
    const skus=activeCat==="Overall"?(_allSkus.length?_allSkus:["SKU-001","SKU-002"]):((skuMap[stockSub]&&skuMap[stockSub][activeCat])||["SKU-001","SKU-002"]);
    const skuPerMc=Math.max(1,Math.ceil(skus.length/machines.length));
    const detailRows=[];
    machines.forEach((mc,i)=>{
      for(let j=0;j<skuPerMc;j++){
        const idx=i*skuPerMc+j;
        if(idx>=skus.length)break;
        const sku=skus[idx];
        const plan=120+i*40+j*30;
        const act=Math.round(plan*(0.85+i*0.025+j*0.01));
        detailRows.push({mc,sku,plan,act});
      }
    });
    const machAgg={};
    detailRows.forEach(r=>{if(!machAgg[r.mc])machAgg[r.mc]={mc:r.mc,plan:0,act:0,skus:0};machAgg[r.mc].plan+=r.plan;machAgg[r.mc].act+=r.act;machAgg[r.mc].skus++;});
    const machRows=Object.values(machAgg).map(r=>({...r,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    const skuAgg={};
    detailRows.forEach(r=>{if(!skuAgg[r.sku])skuAgg[r.sku]={sku:r.sku,plan:0,act:0,machs:new Set()};skuAgg[r.sku].plan+=r.plan;skuAgg[r.sku].act+=r.act;skuAgg[r.sku].machs.add(r.mc);});
    const skuRows=Object.values(skuAgg).map(r=>({...r,machCount:r.machs.size,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    const bothRows=detailRows.map(r=>({...r,achievement:((r.act/r.plan)*100).toFixed(1)+"%"}));
    const rawRows=prodView==="machine"?machRows:prodView==="sku"?skuRows:bothRows;
    const filtered=rawRows.filter(r=>{if(!machSearch)return true;if(prodView==="sku")return [...r.machs].some(m=>m.toLowerCase().includes(machSearch.toLowerCase()));return r.mc.toLowerCase().includes(machSearch.toLowerCase());});
    /* Unit conversion: ~3.87 kg per unit (from 4820 kg / 1245 units) */
    const activeUnit=prodUnit||"Units";
    const unitFactor=activeUnit==="Kg"?3.87:1;
    const unitLbl=activeUnit==="Kg"?"kg":"units";
    const colCfg=prodView==="machine"?["Machine","SKUs","Planned ("+unitLbl+")","Actual ("+unitLbl+")","Achievement"]:prodView==="sku"?["Item Code (SKU)","Machines","Planned ("+unitLbl+")","Actual ("+unitLbl+")","Achievement"]:["Machine","Item Code (SKU)","Planned ("+unitLbl+")","Actual ("+unitLbl+")","Achievement"];
    return(<Card title={stockSub+" \u2014 "+activeCat} accent={C.tl}>
      <div style={{display:"flex",alignItems:"center",gap:14,marginTop:4,marginBottom:8,flexWrap:"wrap"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>View by</span>
          <div style={{display:"flex",gap:4}}>
            {[{k:"machine",l:"Machine"},{k:"sku",l:"SKU"},{k:"both",l:"Machine + SKU"}].map(o=>{const a=prodView===o.k;return(<button key={o.k} onClick={()=>setProdView(o.k)} style={{padding:"5px 12px",borderRadius:6,border:"1px solid "+(a?C.aB:C.bd),background:a?C.aL:C.c2,color:a?C.ac:C.tx,fontSize:12,fontWeight:a?700:500,cursor:"pointer"}}>{o.l}</button>);})}
          </div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>Unit</span>
          <div style={{display:"flex",gap:4}}>
            {[{k:"Units",l:"Units"},{k:"Kg",l:"Kg"}].map(o=>{const a=activeUnit===o.k;return(<button key={o.k} onClick={()=>setProdUnit(o.k)} style={{padding:"5px 12px",borderRadius:6,border:"1px solid "+(a?C.aB:C.bd),background:a?C.aL:C.c2,color:a?C.ac:C.tx,fontSize:12,fontWeight:a?700:500,cursor:"pointer"}}>{o.l}</button>);})}
          </div>
        </div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
        <span style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".3px"}}>Search Machine</span>
        <input type="text" value={machSearch} onChange={e=>setMachSearch(e.target.value)} placeholder={"e.g. "+(machines[0]||"")} style={{padding:"5px 10px",border:"1px solid "+C.bd,borderRadius:6,fontSize:12,outline:"none",width:200,background:C.cd,color:C.tx,fontFamily:"inherit"}}/>
        {machSearch&&<button onClick={()=>setMachSearch("")} style={{padding:"4px 10px",border:"1px solid "+C.bd,borderRadius:6,background:C.c2,fontSize:11,cursor:"pointer",color:C.mu}}>Clear</button>}
        <span style={{marginLeft:"auto",fontSize:11,color:C.mu}}>{filtered.length} of {rawRows.length} rows</span>
      </div>
      <div style={{maxHeight:340,overflowY:"auto",overflowX:"auto",border:"1px solid "+C.bd,borderRadius:6}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
        <thead style={{position:"sticky",top:0,background:C.cd,zIndex:1}}><tr>{colCfg.map((c,i)=>(<th key={i} style={{textAlign:i<=1?"left":"right",padding:"7px 10px",color:C.mu,fontWeight:600,borderBottom:"1px solid "+C.bd,fontSize:12,background:C.cd,textTransform:"uppercase",letterSpacing:".3px"}}>{c}</th>))}</tr></thead>
        <tbody>{filtered.length===0?(<tr><td colSpan={5} style={{padding:"24px 10px",textAlign:"center",color:C.mu,fontSize:13,fontStyle:"italic"}}>No rows match "{machSearch}"</td></tr>):filtered.map((r,i)=>{
          const aNum=parseFloat(r.achievement);
          const aCol=aNum>=100?C.gn:aNum>=95?C.am:C.rd;
          const planVal=Math.round(r.plan*unitFactor);
          const actVal=Math.round(r.act*unitFactor);
          return(<tr key={i} style={{background:i%2===0?"transparent":C.c2}}>
            {prodView==="machine"&&<><td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.tx}}>{r.mc}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",color:C.mu}}>{r.skus}</td></>}
            {prodView==="sku"&&<><td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12,fontWeight:600}}>{r.sku}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",color:C.mu}}>{r.machCount}</td></>}
            {prodView==="both"&&<><td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:600,color:C.tx}}>{r.mc}</td>
              <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12,fontWeight:600}}>{r.sku}</td></>}
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right"}}>{planVal}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:600,color:C.tx}}>{actVal}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:700,color:aCol}}>{r.achievement}</td>
          </tr>);
        })}</tbody>
      </table></div>
    </Card>);
  }

  if(kpi.drillType==="downtime"){
    return(<Card title="Detailed Downtime Log" accent={C.am}>
      <DTable cols={["Code Category","Equipment","Delay Reason","Events","Total DT (Min)","Total DT (Hr)"]} rows={kpi.drillData||[]}/>
    </Card>);
  }

  if(kpi.drillType==="compliance"){
    return(<div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
      <Card title="SKU-wise Plan vs Actual" accent={C.bl}><DTable cols={["SKU","Plan","Actual","Compliance"]} rows={kpi.skuData||[]}/></Card>
      <Card title="Machine-wise Plan vs Actual" accent={C.pp}><DTable cols={["Machine","Plan","Actual","Achievement"]} rows={kpi.machData||[]}/></Card>
    </div>);
  }

  if(kpi.drillType==="budget"){
    return(<Card title="Budget Utilization" accent={C.bl}>
      <div style={{display:"flex",alignItems:"center",gap:16}}>
        <Donut value={85} size={95} color={C.am} label="85%" sub="consumed"/>
        <div>
          <div style={{fontSize:12,color:C.mu}}>Allocated Consumables</div>
          <div style={{fontSize:21,fontWeight:700}}>{"\u20B9"}28.0 L</div>
          <div style={{fontSize:12,color:C.mu,marginTop:6}}>Spent Consumables</div>
          <div style={{fontSize:21,fontWeight:700,color:C.ac}}>{"\u20B9"}23.8 L</div>
        </div>
      </div>
    </Card>);
  }

  if(kpi.drillType==="table"){
    return(<Card title={kpi.drillTitle} accent={C.bl}><DTable cols={kpi.drillCols} rows={kpi.drillRows}/></Card>);
  }
  return null;
}

/* ═══ INVENTORY PAGE ═══ */
function InventoryPage(){
  const pData=[{n:"FG",t:8.4,y:8.1},{n:"Cured",t:6.2,y:5.9},{n:"Green",t:4.8,y:4.5}];
  const sData=[{n:"Tread",t:3.2,y:3.0},{n:"Belt",t:2.8,y:2.6},{n:"Ply",t:4.1,y:3.9},{n:"Capstrip",t:1.5,y:1.4},{n:"Sidewall",t:2.2,y:2.0},{n:"I.Liner",t:1.8,y:1.7},{n:"Bead",t:3.5,y:3.3}];
  const cData=[{n:"Final",t:5.2,y:4.8},{n:"Master",t:3.8,y:3.5}];
  const tblRows=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-i);const ds=d.toLocaleDateString("en-IN",{day:"2-digit",month:"short"});return [ds,8400-i*120,6200-i*80,4800-i*60,3200-i*40,2800-i*30,4100-i*50,1500-i*20,2200-i*25,1800-i*15,3500-i*35,5200-i*60,3800-i*45];});
  const [selBar,setSelBar]=useState(null);

  /* Item-level live inventory per bar group */
  const INV_ITEMS={
    /* Production */
    FG:[
      {code:"FG-P18565R15",desc:"PCR 185/65 R15",qty:2840,unit:"tyres",min:2000,upd:"15-May 18:30"},
      {code:"FG-P19565R15",desc:"PCR 195/65 R15",qty:1920,unit:"tyres",min:2000,upd:"15-May 18:30"},
      {code:"FG-P20555R16",desc:"PCR 205/55 R16",qty:1640,unit:"tyres",min:1800,upd:"15-May 18:30"},
      {code:"FG-21555R17",desc:"PCR 215/55 R17",qty:1480,unit:"tyres",min:1200,upd:"15-May 18:30"},
      {code:"FG-LT23575R15",desc:"LTR 235/75 R15",qty:520,unit:"tyres",min:600,upd:"15-May 18:30"}
    ],
    Cured:[
      {code:"CU-P18565R15",desc:"PCR 185/65 R15 (Cured)",qty:1850,unit:"tyres",min:1500,upd:"15-May 18:30"},
      {code:"CU-P19565R15",desc:"PCR 195/65 R15 (Cured)",qty:1420,unit:"tyres",min:1500,upd:"15-May 18:30"},
      {code:"CU-P20555R16",desc:"PCR 205/55 R16 (Cured)",qty:1180,unit:"tyres",min:1200,upd:"15-May 18:30"},
      {code:"CU-21555R17",desc:"PCR 215/55 R17 (Cured)",qty:980,unit:"tyres",min:900,upd:"15-May 18:30"},
      {code:"CU-LT23575R15",desc:"LTR 235/75 R15 (Cured)",qty:380,unit:"tyres",min:500,upd:"15-May 18:30"}
    ],
    Green:[
      {code:"GT-P18565R15",desc:"PCR 185/65 R15 (Green)",qty:1420,unit:"tyres",min:1200,upd:"15-May 18:30"},
      {code:"GT-P19565R15",desc:"PCR 195/65 R15 (Green)",qty:1180,unit:"tyres",min:1200,upd:"15-May 18:30"},
      {code:"GT-P20555R16",desc:"PCR 205/55 R16 (Green)",qty:920,unit:"tyres",min:1000,upd:"15-May 18:30"},
      {code:"GT-21555R17",desc:"PCR 215/55 R17 (Green)",qty:740,unit:"tyres",min:700,upd:"15-May 18:30"},
      {code:"GT-LT23575R15",desc:"LTR 235/75 R15 (Green)",qty:340,unit:"tyres",min:400,upd:"15-May 18:30"}
    ],
    /* Stock */
    Tread:[
      {code:"TR-PCR-001",desc:"Tread P185\u2013P205 series",qty:1820,unit:"kg",min:1500,upd:"15-May 18:30"},
      {code:"TR-PCR-002",desc:"Tread 215R17 / 225R17",qty:1240,unit:"kg",min:1200,upd:"15-May 18:30"},
      {code:"TR-LTR-001",desc:"Tread LTR 235/75",qty:680,unit:"kg",min:800,upd:"15-May 18:30"}
    ],
    Belt:[
      {code:"BL-PCR-001",desc:"Belt steel ply 1100 dtex",qty:1820,unit:"kg",min:1500,upd:"15-May 18:30"},
      {code:"BL-PCR-002",desc:"Belt steel ply 1670 dtex",qty:980,unit:"kg",min:1100,upd:"15-May 18:30"}
    ],
    Ply:[
      {code:"PL-PCR-001",desc:"Body ply 1670/1 dtex",qty:2840,unit:"kg",min:2200,upd:"15-May 18:30"},
      {code:"PL-PCR-002",desc:"Body ply 1100/1 dtex",qty:1240,unit:"kg",min:1500,upd:"15-May 18:30"}
    ],
    Capstrip:[
      {code:"CS-PCR-001",desc:"Capstrip nylon 940 dtex",qty:680,unit:"kg",min:700,upd:"15-May 18:30"},
      {code:"CS-PCR-002",desc:"Capstrip aramid blend",qty:820,unit:"kg",min:600,upd:"15-May 18:30"}
    ],
    Sidewall:[
      {code:"SW-PCR-001",desc:"Sidewall black PCR",qty:1480,unit:"kg",min:1200,upd:"15-May 18:30"},
      {code:"SW-PCR-002",desc:"Sidewall white letter",qty:720,unit:"kg",min:800,upd:"15-May 18:30"}
    ],
    "I.Liner":[
      {code:"IL-PCR-001",desc:"Inner liner halobutyl",qty:1180,unit:"kg",min:1000,upd:"15-May 18:30"},
      {code:"IL-PCR-002",desc:"Inner liner chlorobutyl",qty:620,unit:"kg",min:700,upd:"15-May 18:30"}
    ],
    Bead:[
      {code:"BD-PCR-001",desc:"Bead wire 0.95mm bronze",qty:2240,unit:"kg",min:1800,upd:"15-May 18:30"},
      {code:"BD-PCR-002",desc:"Bead wire 1.30mm",qty:1280,unit:"kg",min:1400,upd:"15-May 18:30"}
    ],
    /* Compound */
    Final:[
      {code:"MS66",desc:"Sidewall black final",qty:3240,unit:"kg",min:2500,upd:"15-May 18:30"},
      {code:"MS67",desc:"Tread cap final",qty:4280,unit:"kg",min:3500,upd:"15-May 18:30"},
      {code:"MS68",desc:"Tread base final",qty:2180,unit:"kg",min:2200,upd:"15-May 18:30"},
      {code:"MS70",desc:"Apex final",qty:1480,unit:"kg",min:1500,upd:"15-May 18:30"},
      {code:"MS72",desc:"Bead filler final",qty:1820,unit:"kg",min:1400,upd:"15-May 18:30"}
    ],
    Master:[
      {code:"MB76",desc:"NR master batch",qty:5280,unit:"kg",min:4000,upd:"15-May 18:30"},
      {code:"MB614",desc:"SBR master batch",qty:3420,unit:"kg",min:3500,upd:"15-May 18:30"},
      {code:"MB218",desc:"BR master batch",qty:2640,unit:"kg",min:2500,upd:"15-May 18:30"},
      {code:"MB405",desc:"Silica master batch",qty:1840,unit:"kg",min:2200,upd:"15-May 18:30"}
    ]
  };
  const onBarClick=cat=>name=>{
    if(selBar&&selBar.cat===cat&&selBar.name===name)setSelBar(null);
    else setSelBar({cat,name});
  };

  return(<div style={{padding:"16px 20px",display:"flex",flexDirection:"column",gap:14}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <div style={{fontSize:19,fontWeight:700}}>Inventory</div>
      <div style={{display:"flex",gap:8,alignItems:"center"}}>
        <span style={{fontSize:13,color:C.mu,padding:"4px 10px",border:"1px solid "+C.bd,borderRadius:6,background:C.c2}}>Today</span>
        <span style={{fontSize:13,color:C.mu,padding:"4px 10px",border:"1px solid "+C.bd,borderRadius:6,background:C.c2}}>Date Range</span>
        <span style={{fontSize:13,color:C.ac,padding:"4px 10px",border:"1px solid "+C.aB,borderRadius:6,background:C.aL,fontWeight:600,cursor:"pointer"}}>{"\u2913"} Download</span>
      </div>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:12}}>
      <Card title={"Production (in '000s Tyres)"} accent={C.bl}>
        <div style={{display:"flex",gap:8,marginBottom:8}}><span style={{fontSize:12,display:"flex",alignItems:"center",gap:3}}><span style={{width:8,height:8,borderRadius:2,background:C.bl}}/> Today</span><span style={{fontSize:12,display:"flex",alignItems:"center",gap:3}}><span style={{width:8,height:8,borderRadius:2,background:C.mu,opacity:0.6}}/> Yesterday</span></div>
        <GBar groups={pData} h={100} onClick={onBarClick("Production")} selected={selBar&&selBar.cat==="Production"?selBar.name:null}/>
      </Card>
      <Card title={"Stock Inventory (in '000s Tyres)"} accent={C.tl}>
        <div style={{display:"flex",gap:8,marginBottom:8}}><span style={{fontSize:12,display:"flex",alignItems:"center",gap:3}}><span style={{width:8,height:8,borderRadius:2,background:C.bl}}/> Today</span><span style={{fontSize:12,display:"flex",alignItems:"center",gap:3}}><span style={{width:8,height:8,borderRadius:2,background:C.mu,opacity:0.6}}/> Yesterday</span></div>
        <GBar groups={sData} h={100} onClick={onBarClick("Stock")} selected={selBar&&selBar.cat==="Stock"?selBar.name:null}/>
      </Card>
      <Card title={"Compound Inventory (in '000s Tyres)"} accent={C.ac}>
        <div style={{display:"flex",gap:8,marginBottom:8}}><span style={{fontSize:12,display:"flex",alignItems:"center",gap:3}}><span style={{width:8,height:8,borderRadius:2,background:C.bl}}/> Today</span><span style={{fontSize:12,display:"flex",alignItems:"center",gap:3}}><span style={{width:8,height:8,borderRadius:2,background:C.mu,opacity:0.6}}/> Yesterday</span></div>
        <GBar groups={cData} h={100} onClick={onBarClick("Compound")} selected={selBar&&selBar.cat==="Compound"?selBar.name:null}/>
      </Card>
    </div>

    {/* Item-level drill: live inventory for the selected bar */}
    {selBar&&INV_ITEMS[selBar.name]&&(()=>{
      const items=INV_ITEMS[selBar.name];
      const tot=items.reduce((a,b)=>a+b.qty,0);
      const acc=selBar.cat==="Production"?C.bl:selBar.cat==="Stock"?C.tl:C.ac;
      return(<Card title={selBar.cat+" \u2014 "+selBar.name+" \u2014 Item-level Live Inventory"} accent={acc}>
        <div style={{display:"flex",gap:14,alignItems:"center",marginBottom:10,fontSize:12,color:C.mu,flexWrap:"wrap"}}>
          <span><span style={{color:C.tx,fontWeight:700,fontSize:14}}>{items.length}</span> item codes</span>
          <span style={{color:C.bd}}>{"\u2022"}</span>
          <span>Total: <span style={{color:C.tx,fontWeight:700,fontSize:14}}>{tot.toLocaleString()}</span> {items[0].unit}</span>
        </div>
        <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
          <thead><tr style={{background:C.c2}}>{["Item Code","Description","Live Stock"].map((c,i)=>(<th key={i} style={{textAlign:i===2?"right":"left",padding:"7px 10px",color:C.md,fontWeight:700,borderBottom:"1px solid "+C.bd,fontSize:12,textTransform:"uppercase",letterSpacing:".3px"}}>{c}</th>))}</tr></thead>
          <tbody>{items.map((it,i)=>(<tr key={i} style={{background:i%2===0?C.cd:C.c2}}>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,fontWeight:700,fontFamily:"ui-monospace,Menlo,monospace",fontSize:12,color:C.tx}}>{it.code}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,color:C.tx}}>{it.desc}</td>
            <td style={{padding:"8px 10px",borderBottom:"1px solid "+C.bd,textAlign:"right",fontWeight:700,color:C.tx,fontSize:14}}>{it.qty.toLocaleString()} <span style={{fontSize:11,color:C.mu,fontWeight:400}}>{it.unit}</span></td>
          </tr>))}</tbody>
        </table></div>
        <div style={{marginTop:8,fontSize:11,color:C.am,fontWeight:500}}>{"\u25B8"} Click the same bar again to close. Click any other bar to switch.</div>
      </Card>);
    })()}

    <Card title="Daily Inventory (in terms of Tyres)" accent={C.cy}>
      <DTable cols={["Date","FG","Cured","Green","Tread","Belt","Ply","Capstrip","Sidewall","I.Liner","Bead","Final Comp","Master Comp"]} rows={tblRows.map(r=>r.map(c=>typeof c==="number"?fmt(c):c))}/>
    </Card>
  </div>);
}

/* ═══ MAIN DASHBOARD ═══ */
function ProductionDashboard({plant,onBack}){
  const [secId,setSecId]=useState("TBM");
  const [catId,setCatId]=useState("P");
  const [tf,setTf]=useState("Today");
  const [shift,setShift]=useState("All");
  const _r0=_rangeFromPreset("Today");
  const [tfFrom,setTfFrom]=useState(_r0.from);
  const [tfTo,setTfTo]=useState(_r0.to);
  const [openKpi,setOpenKpi]=useState(null);
  const [drillSub,setDrillSub]=useState("");
  const [spcP,setSpcP]=useState(0);
  const [stockSub,setStockSub]=useState("4 Roll");
  /* Section-level sub-category. Drives KPI values + drill content for Production/Plan Compliance/FTQ/Scrap/Rework/NCM Hold */
  const PROD_SUB_OPTIONS={MIX:["Master Compound","Final Compound"],TBM:["Passenger Radial","LT Radial","SCV Radial"],CUR:["Passenger Radial","LT Radial","SCV Radial"]};
  /* BRD §13.3 — product types per Stock sub-section. "Overall" first =
     the sub-section total (shown when no specific product type is picked). */
  const STK_PROD_SUB={"4 Roll":["Overall","Rubberised Ply Production","Rubberised Belt Production"],"Extruder":["Overall","Sidewall Production","Tread Production"],"3 Roll":["Overall","Inner Liner Production"],"Cutter":["Overall","Ply Production","Belt Production"],"Slitter":["Overall","Cap Strip Production","Chafer Production"]};
  const subOptions=secId==="STK"?(STK_PROD_SUB[stockSub]||[]):(PROD_SUB_OPTIONS[secId]||[]);
  const [prodSub,setProdSub]=useState(subOptions[0]||"");
  useEffect(()=>{setProdSub(subOptions[0]||"");setOpenKpi(null);setDrillSub("");},[secId,stockSub]);
  const [tyreType,setTyreType]=useState(isBanmorePlant(plant)?"PCR":"All");
  const [trendKpi,setTrendKpi]=useState(null);

  const sec=SEC.find(s=>s.id===secId);
  const cat=TABS.find(c=>c.id===catId);
  const isInv=catId==="I";
  const kpis=isInv?[]:buildKpis(sec,catId,stockSub,prodSub);
  const toggle=id=>{setOpenKpi(openKpi===id?null:id);setDrillSub("");setSpcP(0);};
  const openKpiObj=openKpi?kpis.find(k=>k.id===openKpi):null;

  return(<div style={{minHeight:"100vh",background:C.bg,fontFamily:"'IBM Plex Sans',system-ui,sans-serif",color:C.tx,fontSize:16}}>
    {/* Top Branding Bar */}
    <div style={{background:C.cd,borderBottom:"1px solid "+C.bd,padding:"0 20px",height:90,display:"flex",alignItems:"center",justifyContent:"space-between",position:"sticky",top:0,zIndex:100,boxShadow:"0 1px 4px rgba(0,0,0,.04)"}}>
      <div style={{display:"flex",alignItems:"center",gap:14}}>
        <button onClick={onBack} style={{width:32,height:32,borderRadius:8,border:"1px solid "+C.bd,background:C.c2,color:C.mu,fontSize:18,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}} title="Back to Plant Map">{"\u2190"}</button>
        <img src={LOGO} alt="JK Tyre" style={{height:80,objectFit:"contain"}}/>
        <div style={{width:1,height:40,background:C.bd}}/>
        <div>
          <div style={{fontSize:18,fontWeight:700,letterSpacing:"-.2px"}}>One Factory</div>
          <div style={{fontSize:11,color:C.mu,textTransform:"uppercase",letterSpacing:"1px",marginTop:1}}>Production Head Dashboard</div>
        </div>
        <span style={{fontSize:13,color:C.ac,fontWeight:700,background:C.aL,padding:"3px 10px",borderRadius:8,marginLeft:4}}>{plant?plant.name.split(" ")[0].toUpperCase():"BTP"}</span>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        <TimeRangeSelect preset={tf} setPreset={setTf} from={tfFrom} to={tfTo} setFrom={setTfFrom} setTo={setTfTo} shift={shift} setShift={setShift}/>
        <TyreTypeFilter value={tyreType} onChange={setTyreType} plant={plant}/>
        <ExportButton/>
        <UserMenu plant={plant} role="PH" onLogout={onBack}/>
      </div>
    </div>

    {/* Tabs Row */}
    <div style={{background:C.cd,borderBottom:"1px solid "+C.bd,padding:"0 12px",display:"flex",alignItems:"center",overflowX:"auto",position:"sticky",top:90,zIndex:99}}>
      {TABS.map(t=>{const a=catId===t.id;return(<button key={t.id} onClick={()=>{setCatId(t.id);setOpenKpi(null);setDrillSub("");}} style={{padding:"8px 12px",border:"none",borderBottom:a?"2px solid "+t.c:"2px solid transparent",background:"transparent",fontSize:13,fontWeight:a?700:400,color:a?t.c:C.mu,cursor:"pointer",display:"flex",alignItems:"center",gap:4,whiteSpace:"nowrap",flexShrink:0}}><span style={{fontSize:14,opacity:a?1:0.5}}>{t.i}</span>{t.n}<span style={{fontSize:11,fontWeight:700,padding:"1px 3px",borderRadius:3,background:a?t.c+"20":"transparent",color:a?t.c:C.mu}}>{t.id}</span></button>);})}
      {!isInv&&<><div style={{flex:1}}/><div style={{fontSize:13,color:C.md,flexShrink:0}}>{sec.fl}{secId==="STK"?" \u2014 "+stockSub:""}</div></>}
    </div>

    {isInv?<InventoryPage/>:(
    <div style={{display:"flex",minHeight:"calc(100vh - 126px)"}}>
      {/* Sidebar */}
      <div style={{width:160,minWidth:160,background:C.cd,borderRight:"1px solid "+C.bd,padding:"8px 0",display:"flex",flexDirection:"column",position:"sticky",top:126,height:"calc(100vh - 126px)",overflowY:"auto",flexShrink:0}}>
        <div style={{padding:"0 10px 6px",fontSize:11,fontWeight:700,color:C.ac,textTransform:"uppercase",letterSpacing:"1.5px"}}>Sections</div>
        {SEC.map((s,i)=>{const act=secId===s.id;const v=s.oee;const c=rc(v);return(<div key={s.id}>
          <div onClick={()=>{setSecId(s.id);setOpenKpi(null);setDrillSub("");if(s.id==="STK")setStockSub("4 Roll");}} style={{padding:"6px 10px",cursor:"pointer",display:"flex",alignItems:"center",gap:6,background:act?C.aL:"transparent",borderLeft:act?"2px solid "+C.ac:"2px solid transparent"}}>
            <div style={{position:"relative",width:30,height:30,flexShrink:0}}><Ring value={v} size={30} stroke={3} color={c}/><div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:700,color:c}}>{Math.round(v)}</div></div>
            <div style={{flex:1,minWidth:0}}><div style={{fontSize:13,fontWeight:act?700:400,color:act?C.ac:C.tx,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{s.nm}</div><div style={{fontSize:11,color:C.mu}}>OEE: {v}%</div></div>
          </div>
          {i<SEC.length-1&&<div style={{display:"flex",justifyContent:"center",padding:"1px 0"}}><svg width="6" height="8" viewBox="0 0 12 16"><path d="M6 3v10M4 10l2 3 2-3" stroke={C.bd} strokeWidth="1.5" fill="none" strokeLinecap="round"/></svg></div>}
        </div>);})}
        <div style={{marginTop:"auto",padding:"8px 10px",borderTop:"1px solid "+C.bd}}>
          <div style={{fontSize:11,color:C.mu,textTransform:"uppercase",letterSpacing:".8px",marginBottom:2}}>Plant</div>
          <div style={{fontSize:18,fontWeight:700,color:rc(PLANT.oee)}}>{PLANT.oee}%<span style={{fontSize:11,color:C.mu,fontWeight:400,marginLeft:2}}>OEE</span></div>
          <div style={{display:"flex",flexWrap:"wrap",gap:2,marginTop:3}}>{[{l:"Prod",v:fmt(PLANT.prodCount)+" nos",c:C.gn},{l:"Scrap",v:PLANT.scrap+"%",c:C.rd}].map(x=>(<span key={x.l} style={{fontSize:11,fontWeight:600,color:x.c,background:x.c+"18",padding:"1px 4px",borderRadius:3}}>{x.l}:{x.v}</span>))}</div>
        </div>
      </div>

      {/* Main */}
      <div style={{flex:1,padding:"10px 14px 40px",display:"flex",flexDirection:"column",gap:10,overflowY:"auto",overflowX:"hidden",minWidth:0}}>
        {/* Header */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:6}}>
          <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
            <div style={{fontSize:17,fontWeight:700}}>{sec.fl}</div>
            <span style={{width:6,height:6,borderRadius:"50%",background:rc(sec.oee)}}/>
            <span style={{fontSize:13,fontWeight:600,color:rc(sec.oee)}}>{sec.oee}% OEE</span>
            <span style={{fontSize:12,fontWeight:700,color:cat.c,background:cat.c+"18",padding:"2px 7px",borderRadius:8}}>{cat.i} {cat.n}</span>
          </div>
        </div>

        {/* Stock sub-selector */}
        {secId==="STK"&&<div style={{display:"flex",gap:4,padding:"6px 0"}}>
          {STOCK_SUBS.map(ss=>(<button key={ss} onClick={()=>{setStockSub(ss);setOpenKpi(null);setDrillSub("");}} style={{padding:"5px 14px",borderRadius:999,border:"1px solid "+(stockSub===ss?C.aB:C.bd),background:stockSub===ss?C.aL:C.c2,color:stockSub===ss?C.ac:C.tx,fontSize:13,fontWeight:600,cursor:"pointer"}}>{ss}</button>))}
        </div>}

        {/* Mixing Master/Final selector moved into Production drill-down */}

        {/* Section-level sub-category strip — drives Production, Plan Compliance, FTQ, Scrap, Rework, NCM Hold KPI cards */}
        {(catId==="P"||catId==="Q")&&subOptions.length>0&&<div style={{display:"flex",gap:4,padding:"6px 0",flexWrap:"wrap"}}>
          {subOptions.map(opt=>(<button key={opt} onClick={()=>{setProdSub(opt);setOpenKpi(null);setDrillSub("");}} style={{padding:"5px 14px",borderRadius:999,border:"1px solid "+(prodSub===opt?C.aB:C.bd),background:prodSub===opt?C.aL:C.c2,color:prodSub===opt?C.ac:C.tx,fontSize:13,fontWeight:600,cursor:"pointer"}}>{opt}</button>))}
        </div>}

        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8}}>
          <div style={{fontSize:12,color:C.am,fontWeight:600}}>{"\u25B8"} Click any KPI card to expand drill-down</div>
          <TyreTypeBanner tt={tyreType} plant={plant}/>
        </div>

        {/* KPI Cards */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(190px,1fr))",gap:8}}>
          {kpis.map(k=>(<KpiCard key={k.id} kpi={k} isOpen={openKpi===k.id} onToggle={()=>toggle(k.id)} onTrend={setTrendKpi} tyreType={tyreType} plant={plant}/>))}
        </div>

        {/* Drill Panel */}
        {openKpiObj&&<div style={{animation:"fadeIn .2s ease"}}><DrillPanel kpi={openKpiObj} sub={drillSub} setSub={setDrillSub} spcP={spcP} setSpcP={setSpcP}/></div>}

        {/* Productivity extras */}
        {catId==="P"&&(()=>{const u=sec.id==="MIX"?"MT":sec.id==="STK"?"units":"nos";return(<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(250px,1fr))",gap:10}}>
          <Card title="Shift Comparison" accent={C.tl}>
            <DTable cols={["Shift","Plan ("+u+")","Actual ("+u+")","FTQ%","OEE%"]} rows={[
              ["Shift A",Math.round(sec.oee*4.2),Math.round(sec.oee*3.9),(100-sec.sc-0.3).toFixed(1)+"%",(sec.oee+1.5).toFixed(1)+"%"],
              ["Shift B",Math.round(sec.oee*3.8),Math.round(sec.oee*3.2),(100-sec.sc-1.5).toFixed(1)+"%",(sec.oee-3).toFixed(1)+"%"],
              ["Shift C",Math.round(sec.oee*3.5),Math.round(sec.oee*3.3),(100-sec.sc).toFixed(1)+"%",(sec.oee-0.5).toFixed(1)+"%"]
            ]}/>
          </Card>
        </div>);})()}

        {/* Cost extras */}
        {catId==="C"&&openKpiObj&&openKpiObj.drillType==="budget"&&null}

        {/* Safety Record and Manpower Summary strips removed per request */}
      </div>
    </div>)}

    <style>{`@keyframes fadeIn{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}`}</style>
    {trendKpi&&<TrendPanel kpi={trendKpi} onClose={()=>setTrendKpi(null)} tyreType={tyreType} plant={plant}/>}
  </div>);
}


/* ════════════════════════════════════════════════════════════════════
   ═══ QUALITY HEAD DASHBOARD ═══
   3 Tabs: Process | Product | Customer Complaint
   ════════════════════════════════════════════════════════════════════ */

/* ═══ STATUS PILL ═══ */
function StatusPill({status}){
  const map={
    Green:{bg:C.gn+"18",fg:C.gn,t:"Green"},Yellow:{bg:C.am+"18",fg:C.am,t:"Yellow"},Red:{bg:C.rd+"18",fg:C.rd,t:"Red"},Grey:{bg:"#9CA3AF18",fg:"#6B7280",t:"Manual"},
    Open:{bg:C.am+"18",fg:C.am,t:"Open"},Closed:{bg:C.gn+"18",fg:C.gn,t:"Closed"},Overdue:{bg:C.rd+"18",fg:C.rd,t:"Overdue"},Pending:{bg:C.am+"18",fg:C.am,t:"Pending"},
    Released:{bg:C.gn+"18",fg:C.gn,t:"Released"},Hold:{bg:C.rd+"18",fg:C.rd,t:"Hold"},Accepted:{bg:C.gn+"18",fg:C.gn,t:"Accepted"},Rejected:{bg:C.rd+"18",fg:C.rd,t:"Rejected"},
    Manual:{bg:"#9CA3AF18",fg:"#6B7280",t:"Manual"}
  };
  const s=map[status]||{bg:C.bd,fg:C.mu,t:status};
  return <span style={{padding:"2px 8px",borderRadius:999,fontSize:12,fontWeight:700,background:s.bg,color:s.fg,whiteSpace:"nowrap"}}>{s.t}</span>;
}

/* ═══ BREADCRUMB ═══ */
function Breadcrumb({path,onNav}){
  return(<div style={{display:"flex",alignItems:"center",gap:6,fontSize:13,color:C.mu,marginBottom:8,flexWrap:"wrap"}}>
    {path.map((p,i)=>(<span key={i} style={{display:"flex",alignItems:"center",gap:6}}>
      <span onClick={()=>onNav&&onNav(i)} style={{cursor:onNav&&i<path.length-1?"pointer":"default",color:i===path.length-1?C.tx:C.mu,fontWeight:i===path.length-1?700:400,textDecoration:onNav&&i<path.length-1?"underline":"none"}}>{p}</span>
      {i<path.length-1&&<span style={{color:C.bd}}>{"\u203A"}</span>}
    </span>))}
  </div>);
}

/* ═══ MINI CONTROL CHART (SPC) ═══ */
function ControlChart({data,ucl,lcl,target,w=240,h=80}){
  const mn=Math.min(...data,lcl)-0.05,mx=Math.max(...data,ucl)+0.05,rn=mx-mn||1;
  const yScale=v=>h-((v-mn)/rn)*(h-10)-5;
  const pts=data.map((v,i)=>`${10+(i/(data.length-1))*(w-20)},${yScale(v)}`).join(" ");
  return(<svg width={w} height={h} style={{background:C.c2,borderRadius:4,border:"1px solid "+C.bd}}>
    <line x1="10" x2={w-10} y1={yScale(ucl)} y2={yScale(ucl)} stroke={C.rd} strokeWidth="1" strokeDasharray="3,2"/>
    <line x1="10" x2={w-10} y1={yScale(lcl)} y2={yScale(lcl)} stroke={C.rd} strokeWidth="1" strokeDasharray="3,2"/>
    <line x1="10" x2={w-10} y1={yScale(target)} y2={yScale(target)} stroke={C.gn} strokeWidth="1" strokeDasharray="2,2"/>
    <text x={w-8} y={yScale(ucl)-2} fontSize="7" fill={C.rd} textAnchor="end">UCL {ucl}</text>
    <text x={w-8} y={yScale(lcl)+8} fontSize="7" fill={C.rd} textAnchor="end">LCL {lcl}</text>
    <polyline points={pts} fill="none" stroke={C.bl} strokeWidth="1.5"/>
    {data.map((v,i)=>{const oob=v>ucl||v<lcl;return <circle key={i} cx={10+(i/(data.length-1))*(w-20)} cy={yScale(v)} r="2.5" fill={oob?C.rd:C.bl}/>;})}
  </svg>);
}

/* ═══ KPI CARD (Quality variant with status) ═══ */
function QKpiCard({kpi,isOpen,onToggle,onTrend,tyreType,plant}){
  const stCol=kpi.status==="Red"?C.rd:kpi.status==="Yellow"?C.am:kpi.status==="Grey"?"#6B7280":C.gn;
  const v=tAdjust(kpi.v,kpi.n,tyreType,plant);
  const trendClick=e=>{e.stopPropagation();if(onTrend)onTrend(kpi);};
  return(<div onClick={onToggle} style={{background:C.cd,borderRadius:C.r,border:"1px solid "+(isOpen?C.ac+"88":C.bd),boxShadow:isOpen?"0 0 0 1px "+C.ac+"40, "+C.sh:C.sh,cursor:kpi.drill?"pointer":"default",overflow:"hidden",transition:"border-color .2s",borderLeft:"3px solid "+stCol}}>
    <div style={{padding:"10px 12px"}}>
      <div style={{fontSize:11,color:C.mu,fontWeight:600,textTransform:"uppercase",letterSpacing:".5px",marginBottom:4,display:"flex",justifyContent:"space-between",alignItems:"center",gap:6}}>
        <span style={{flex:1,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{kpi.n}{kpi.manual&&<span style={{marginLeft:4,fontSize:11,padding:"1px 4px",background:"#9CA3AF22",color:"#6B7280",borderRadius:3}}>MANUAL</span>}</span>
        <div style={{display:"flex",alignItems:"center",gap:4,flexShrink:0}}>
          <button onClick={trendClick} title="View Trend (Daily / Monthly / Yearly)" style={{width:20,height:20,borderRadius:4,border:"1px solid "+C.bd,background:C.c2,color:C.mu,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",padding:0}}><TrendIcon size={11}/></button>
          {kpi.drill&&<span title="Click card to drill down" style={{color:isOpen?C.ac:C.mu,transform:isOpen?"rotate(180deg)":"",transition:"transform .2s",fontSize:13}}>{"\u25BC"}</span>}
        </div>
      </div>
      <div style={{display:"flex",alignItems:"flex-end",justifyContent:"space-between"}}>
        <div style={{display:"flex",alignItems:"baseline",gap:3}}>
          <span style={{fontSize:22,fontWeight:700,color:C.tx}}>{v}</span>
          {kpi.u&&<span style={{fontSize:12,color:C.mu}}>{kpi.u}</span>}
        </div>
        {kpi.sp&&<Spark data={kpi.sp} color={stCol}/>}
      </div>
      <div style={{marginTop:4,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        {kpi.target&&<span style={{fontSize:12,color:C.mu}}>Target: {kpi.target}</span>}
        {kpi.status&&<StatusPill status={kpi.status}/>}
      </div>
    </div>
  </div>);
}

