function ProjectDrill({kpi,sub,setSub}){
  if(!kpi) return null;
  if(kpi.drill==="act"||kpi.drill==="sts"){
    const list=kpi.drill==="sts"?PROJECTS.filter(p=>p.st==="Delayed"):PROJECTS;
    const baseCols=["ID","Project","Value","Owner","% Complete","ETA","Status"];
    const cols=kpi.drill==="sts"?baseCols.concat(["Delay Reason"]):baseCols;
    const rows=list.map(p=>{
      const progressBar=<div style={{display:"flex",alignItems:"center",gap:6}}><div style={{width:60,height:6,background:C.bd,borderRadius:3,overflow:"hidden"}}><div style={{width:p.pct+"%",height:"100%",background:p.pct>70?C.gn:p.pct>40?C.am:C.bl}}/></div><span style={{fontSize:13,fontWeight:600}}>{p.pct}%</span></div>;
      const baseRow=[p.id,p.n,p.val,p.own,progressBar,p.eta,<StatusPill status={p.st==="On-track"?"Green":"Red"}/>];
      if(kpi.drill==="sts") baseRow.push(p.delay||"-");
      return baseRow;
    });
    return(<Card title={kpi.drill==="sts"?"Delayed Projects":"Active Capex Projects"} accent={C.bl}>
      <Breadcrumb path={["Projects",kpi.drill==="sts"?"Delayed":"Active"]}/>
      <DTable cols={cols} rows={rows}/>
    </Card>);
  }
  if(kpi.drill==="bud"){
    return(<Card title="Budget Utilization" accent={C.bl}>
      <Breadcrumb path={["Projects","Budget"]}/>
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:10}}>
        <div style={{padding:"10px 12px",background:C.c2,borderRadius:6,border:"1px solid "+C.bd,textAlign:"center"}}><div style={{fontSize:11,color:C.mu,textTransform:"uppercase"}}>Allocated</div><div style={{fontSize:21,fontWeight:700}}>₹6.5 Cr</div></div>
        <div style={{padding:"10px 12px",background:C.gn+"10",borderRadius:6,border:"1px solid "+C.gn+"33",textAlign:"center"}}><div style={{fontSize:11,color:C.gn,textTransform:"uppercase",fontWeight:700}}>Spent</div><div style={{fontSize:21,fontWeight:700,color:C.gn}}>₹4.2 Cr</div></div>
        <div style={{padding:"10px 12px",background:C.bl+"10",borderRadius:6,border:"1px solid "+C.bl+"33",textAlign:"center"}}><div style={{fontSize:11,color:C.bl,textTransform:"uppercase",fontWeight:700}}>Remaining</div><div style={{fontSize:21,fontWeight:700,color:C.bl}}>₹2.3 Cr</div></div>
      </div>
      <DTable cols={["Project","Budget","Spent","% Used"]} rows={PROJECTS.slice(0,5).map(p=>{const sp=(parseFloat(p.val.replace("\u20B9","").replace(" Cr","").replace(" L",""))*(p.val.includes("Cr")?1:0.01)*(p.pct/100)).toFixed(2);return[p.n,p.val,"\u20B9"+sp+" Cr",p.pct+"%"];})}/>
    </Card>);
  }
  if(kpi.drill==="ms"){
    return(<Card title="Major Milestones \u2014 Next 7 Days" accent={C.am}>
      <Breadcrumb path={["Projects","Milestones"]}/>
      <DTable cols={["Date","Project","Milestone","Owner","Pre-requisite Status","Risk"]} rows={[
        ["18-Apr","Quintoflex modification","Trial run","Eng Head","Ready",<StatusPill status="Green"/>],
        ["20-Apr","ETP expansion","Civil work approval","Util Mgr","Pending",<StatusPill status="Red"/>],
        ["22-Apr","Solar rooftop","Net metering test","Util Mgr","Ready",<StatusPill status="Green"/>]
      ]}/>
    </Card>);
  }
  if(kpi.drill==="mr"){
    return(<Card title="Modification Requests Pending" accent={C.am}>
      <Breadcrumb path={["Projects","Modification Requests"]}/>
      <DTable cols={["MR #","Requestor","Machine","Scope","Cost Est.","Age","Status"]} rows={[
        ["MR-145","Production","TBM-2","Auto bead handling","\u20B98 L",12,<StatusPill status="Pending"/>],
        ["MR-146","Quality","Press-08","Sensor addition","\u20B92 L",8,<StatusPill status="Pending"/>],
        ["MR-148","Safety","Compressor area","Guard upgrade","\u20B91.5 L",5,<StatusPill status="Open"/>],
        ["MR-150","Production","Banbury-2","Cooling enhancement","\u20B96 L",3,<StatusPill status="Open"/>]
      ]}/>
    </Card>);
  }
  return null;
}

